window.GRADES=window.GRADES||{};GRADES["3"]={subjects:[{"id":"ing2","name":"Inglés","emo":"🇬🇧","tag":"Prueba de inglés","desc":"Programas de 2º y 3º · Open Day 1 y Brighter Ideas 2","c1":"#FF9F5A","c2":"#FF7A8A","units":[{"id":"starter","dot":"👋","name":"Starter","title":"Starter Unit","sub":"Saludos, instrucciones y útiles","rules":"\n<div class=\"rsec\"><h4>Los saludos van de a pares</h4>\n<p class=\"exline\">Cada pregunta tiene su respuesta fija. Se memorizan juntas, como un par.</p>\n<div class=\"rrow\"><span class=\"rl\">Goodbye!</span><span class=\"ra\">See you tomorrow!</span></div>\n<p class=\"exline\">No hay regla que estudiar: hay que reconocer qué responde a qué.</p></div>\n<div class=\"rsec\"><h4>El apóstrofe borra una letra</h4>\n<div class=\"rrow\"><span class=\"rl\">He's</span><span class=\"ra\">= He is</span></div>\n<div class=\"rrow\"><span class=\"rl\">That's</span><span class=\"ra\">= That is</span></div>\n<p class=\"exline\">Siempre funciona igual: se junta el verbo con la palabra de antes y la letra que falta se reemplaza por el apóstrofe.</p></div>\n<div class=\"rsec\"><h4>Las instrucciones son órdenes</h4>\n<p class=\"exline\">El verbo va <b>primero y solo</b>, sin sujeto adelante.</p>\n<div class=\"rrow\"><span class=\"rl\">Listen!</span><span class=\"ra\">¡Escuchá!</span></div>\n<div class=\"warn\">Para traducir una instrucción, fijate en el <b>verbo</b>: es la primera palabra y es la que manda. Las que vienen después dicen sobre qué.</div></div>\n<div class=\"rsec\"><h4>Preguntar qué es algo</h4>\n<p class=\"exline\">A <b>What is it?</b> se contesta con <b>It's a</b> + el objeto.</p>\n<div class=\"rrow\"><span class=\"rl\">What is it?</span><span class=\"ra\">It's a box.</span></div></div>","ex":[{"t":"match","q":"Uní cada pregunta con su respuesta","pairs":[["What's your name?","My name's Ana."],["How are you?","I'm fine, thanks!"],["Hello!","Hi!"],["Good morning!","Good morning, Miss!"]]},{"t":"choice","q":"La maestra dice: <span class='en'>Stand up</span>","h":"¿Qué tenés que hacer?","o":["Pararme","Sentarme","Abrir el libro"],"a":0},{"t":"choice","q":"<span class='en'>Open your books</span> significa:","o":["Abran los libros","Cierren los libros","Guarden los lápices"],"a":0},{"t":"choice","q":"<span class='en'>Put away your pencils</span> significa:","o":["Saquen los lápices","Guarden los lápices","Presten los lápices"],"a":1},{"t":"choice","q":"<span class='en'>Sit down, please.</span>","o":["Sentate, por favor","Parate, por favor","Cerrá el libro"],"a":0},{"t":"choice","e":"✏️","q":"<span class='en'>What is it?</span>","o":["It's a pencil.","It's a pen.","It's a rubber."],"a":0},{"t":"choice","e":"🎒","q":"<span class='en'>What is it?</span>","o":["It's a ruler.","It's a schoolbag.","It's a book."],"a":1},{"t":"choice","q":"¿Cómo se dice <b>lapicera</b>?","o":["pencil","crayon","pen"],"a":2},{"t":"spell","q":"Escribí en inglés: <b>goma</b>","a":"rubber"},{"t":"spell","q":"Escribí en inglés: <b>regla</b>","a":"ruler"},{"t":"spell","q":"Escribí en inglés: <b>cartuchera</b>","a":"pencil case"},{"t":"choice","q":"<span class='en'>Take out your pencils</span> significa:","o":["Guarden los lápices","Saquen los lápices","Presten los lápices"],"a":1},{"t":"choice","q":"<span class='en'>Close your books</span> significa:","o":["Cierren los libros","Abran los libros","Lean los libros"],"a":0}]},{"id":"u1","dot":"🎂","name":"Unit 1","title":"Unit 1","sub":"How old are you? · he/she · colores y números","rules":"\n<div class=\"rsec\"><h4>El verbo TO BE</h4>\n<div class=\"rrow\"><span class=\"rl\">I</span><span class=\"ra\">am</span></div>\n<div class=\"rrow\"><span class=\"rl\">he / she / it</span><span class=\"ra\">is</span></div>\n<div class=\"rrow\"><span class=\"rl\">you / we / they</span><span class=\"ra\">are</span></div>\n<p class=\"exline\">The cat <b>is</b> small. &nbsp; We <b>are</b> at school.</p>\n<div class=\"warn\">La edad también se dice con <b>to be</b>, no con \"tener\": <b>He is eleven.</b> Literalmente \"él ES once\".</div></div>\n<div class=\"rsec\"><h4>Para preguntar, se da vuelta</h4>\n<div class=\"rrow\"><span class=\"rl\">The dog is big.</span><span class=\"ra\">Is the dog big?</span></div>\n<p class=\"exline\">El verbo salta al principio. Nada más cambia de lugar.</p></div>\n<div class=\"rsec\"><h4>Respuestas cortas</h4>\n<div class=\"rrow\"><span class=\"rl\">Is the dog big?</span><span class=\"ra\">Yes, it is. / No, it isn't.</span></div>\n<div class=\"warn\"><b>&#9888; En el SÍ nunca se contrae.</b><br>\n<span class=\"yes\">&#10003;</span> Yes, he <b>is</b>. &nbsp;&nbsp; <span class=\"no\">&#10007;</span> Yes, he's.<br>\nEn el NO sí se puede: No, he isn't.</div></div>\n<div class=\"rsec\"><h4>HIS o HER: mirá de quién es</h4>\n<div class=\"rrow\"><span class=\"rl\">Pablo &rarr; es varón</span><span class=\"ra\">his bike</span></div>\n<div class=\"rrow\"><span class=\"rl\">Lucía &rarr; es mujer</span><span class=\"ra\">her bike</span></div>\n<div class=\"warn\"><b>&#9888; La trampa:</b> en castellano los dos son <b>\"su\"</b>. En inglés no mirás la cosa, mirás <b>al dueño</b>. La bicicleta de Pablo es <b>his</b> bike aunque \"bicicleta\" sea femenino.</div></div>","ex":[{"t":"choice","q":"<span class='en'>How old are you?</span>","h":"Tenés 6 años","o":["I'm six years old.","I'm fine, thanks.","My name's Tom."],"a":0},{"t":"choice","q":"<span class='en'>Are you seven years old?</span>","h":"Respondé que SÍ","o":["Yes, I am.","Yes, I is.","Yes, I are."],"a":0},{"t":"choice","q":"<span class='en'>Are you seven?</span>","h":"Respondé que NO","o":["No, I not.","No, I'm not.","No, I aren't."],"a":1},{"t":"choice","q":"This is Tom. ___ is seven.","o":["He","She","I"],"a":0},{"t":"choice","q":"This is Mary. ___ isn't six.","o":["He","She","It"],"a":1},{"t":"choice","q":"<span class='en'>How old is she?</span>","h":"Ella tiene 6","o":["He's six.","She's six.","I'm six."],"a":1},{"t":"choice","q":"This is my friend Ben. ___ name is Ben.","o":["Her","His","Your"],"a":1},{"t":"choice","q":"This is Ana. ___ favourite colour is red.","o":["His","Her","My"],"a":1},{"t":"choice","q":"<span class='en'>What colour is your schoolbag?</span>","h":"Es azul 🟦","o":["It's green.","It's blue.","It's black."],"a":1},{"t":"match","q":"Uní el color con su nombre","pairs":[["red","🔴 rojo"],["yellow","🟡 amarillo"],["brown","🟤 marrón"],["orange","🟠 naranja"],["green","🟢 verde"],["black","⚫ negro"],["white","⚪ blanco"],["blue","🔵 azul"]]},{"t":"spell","q":"Escribí el número <b>7</b> en inglés","a":"seven"},{"t":"spell","q":"Escribí el número <b>4</b> en inglés","a":"four"},{"t":"spell","q":"Escribí el número <b>10</b> en inglés","a":"ten"},{"t":"match","q":"Uní cada número con su palabra","pairs":[["one","1"],["two","2"],["three","3"],["five","5"],["six","6"],["eight","8"],["nine","9"]]},{"t":"choice","q":"<span class='en'>What's your favourite colour?</span>","h":"Tu color favorito es el blanco","o":["My favourite colour is white.","I'm white.","It's favourite white."],"a":0}]},{"id":"u2","dot":"👨‍👩‍👧","name":"Unit 2","title":"Unit 2","sub":"We/They are · familia · adjetivos","rules":"\n<div class=\"rsec\"><h4>TO BE en plural</h4>\n<div class=\"rrow\"><span class=\"rl\">we / you / they</span><span class=\"ra\">are</span></div>\n<div class=\"rrow\"><span class=\"rl\">he / she / it</span><span class=\"ra\">is</span></div>\n<p class=\"exline\">You <b>are</b> my friends. &nbsp; The dogs <b>are</b> big.</p></div>\n<div class=\"rsec\"><h4>El negativo</h4>\n<div class=\"rrow\"><span class=\"rl\">he / she / it</span><span class=\"ra\">isn't</span></div>\n<div class=\"rrow\"><span class=\"rl\">we / you / they</span><span class=\"ra\">aren't</span></div>\n<p class=\"exline\">The cat <b>isn't</b> black. &nbsp; They <b>aren't</b> at home.</p></div>\n<div class=\"rsec\"><h4>Regla de oro de las respuestas cortas</h4>\n<p class=\"exline\">Se contesta con <b>el mismo verbo</b> con el que empieza la pregunta.</p>\n<div class=\"rrow\"><span class=\"rl\">Is it big?</span><span class=\"ra\">Yes, it is.</span></div>\n<div class=\"rrow\"><span class=\"rl\">Are we late?</span><span class=\"ra\">No, we aren't.</span></div>\n<div class=\"warn\">Mirá la <b>primera palabra</b> de la pregunta: esa misma, conjugada igual, es la que va en la respuesta.</div></div>\n<div class=\"rsec\"><h4>Adjetivos</h4>\n<p class=\"exline\">Casi todos vienen en <b>pares opuestos</b>. Si te sale uno, pensá cuál sería su contrario: suele ser el que buscás.</p></div>","ex":[{"t":"choice","q":"We ___ tall.","o":["am","is","are"],"a":2},{"t":"choice","q":"They ___ young.","o":["is","are","am"],"a":1},{"t":"choice","q":"<span class='en'>Are they happy?</span>","h":"Respondé que SÍ","o":["Yes, they are.","Yes, they aren't.","Yes, they is."],"a":0},{"t":"choice","q":"<span class='en'>Is he your brother?</span>","h":"Respondé que NO","o":["No, he aren't.","No, he not.","No, he isn't."],"a":2},{"t":"choice","q":"We ___ old. (negativo)","o":["aren't","isn't","not"],"a":0},{"t":"choice","q":"<span class='en'>Is she your sister?</span>","h":"Respondé que SÍ","o":["Yes, she is.","Yes, she are.","Yes, he is."],"a":0},{"t":"match","q":"Uní cada palabra con su significado","pairs":[["mum","mamá"],["dad","papá"],["sister","hermana"],["grandma","abuela"],["grandpa","abuelo"],["brother","hermano"],["dog","perro"],["family","familia"]]},{"t":"choice","q":"Lo contrario de <span class='en'>tall</span> es:","o":["small","short","young"],"a":1},{"t":"choice","q":"Lo contrario de <span class='en'>happy</span> es:","o":["sad","old","tall"],"a":0},{"t":"choice","q":"Lo contrario de <span class='en'>young</span> es:","o":["short","small","old"],"a":2},{"t":"spell","q":"Escribí en inglés: <b>hermana</b>","a":"sister"},{"t":"spell","q":"Escribí en inglés: <b>abuelo</b>","a":"grandpa"},{"t":"choice","q":"¿Cómo se dice <b>hermanito bebé</b>?","o":["baby brother","baby sister","little brother"],"a":0}]},{"id":"u3","dot":"🏠","name":"Unit 3","title":"Unit 3","sub":"There is / There are · preposiciones · la casa","rules":"\n<div class=\"rsec\"><h4>There is / There are = \"hay\"</h4>\n<div class=\"rrow\"><span class=\"rl\">1 sola cosa</span><span class=\"ra\">There is</span></div>\n<div class=\"rrow\"><span class=\"rl\">2 o más</span><span class=\"ra\">There are</span></div>\n<p class=\"exline\">There <b>is</b> a dog in the garden. &nbsp; There <b>are</b> three birds.</p>\n<div class=\"warn\"><b>&#9888; Truco rápido:</b> si el sustantivo termina en <b>-s</b>, va <b>are</b>. Si no, va <b>is</b>.</div></div>\n<div class=\"rsec\"><h4>Preguntas y respuestas</h4>\n<div class=\"rrow\"><span class=\"rl\">Is there a garden? (no)</span><span class=\"ra\">No, there isn't.</span></div>\n<div class=\"rrow\"><span class=\"rl\">Are there any trees? (sí)</span><span class=\"ra\">Yes, there are.</span></div>\n<p class=\"exline\">En la respuesta se repiten <b>there</b> y el mismo verbo de la pregunta (<b>is</b> o <b>are</b>). Para el SÍ va sin negación; para el NO, con <b>n't</b>.</p></div>\n<div class=\"rsec\"><h4>How many…? (cuántos)</h4>\n<div class=\"rrow\"><span class=\"rl\">How many birds are there?</span><span class=\"ra\">There are three.</span></div>\n<p class=\"exline\">Después de <b>How many</b> el sustantivo va en <b>plural</b>, y se contesta con <b>There are</b> + el número.</p></div>\n<div class=\"rsec\"><h4>Preposiciones: el lugar exacto importa</h4>\n<p class=\"exline\">Dos que se confunden todo el tiempo:</p>\n<div class=\"rrow\"><span class=\"rl\">The bird is <b>in</b> the cage</span><span class=\"ra\">adentro</span></div>\n<div class=\"rrow\"><span class=\"rl\">The bird is <b>on</b> the cage</span><span class=\"ra\">tocando la superficie</span></div>\n<div class=\"warn\"><b>&#9888; between</b> necesita siempre <b>dos</b> cosas, una de cada lado. Si hay una sola referencia, no puede ser <i>between</i>.<br>\nAntes de contestar, imaginate la escena y preguntate: ¿adentro, arriba, abajo, atrás, adelante, al costado, o en el medio de dos?</div></div>","ex":[{"t":"choice","q":"There ___ a sofa in the living room.","o":["is","are"],"a":0},{"t":"choice","q":"There ___ four rooms.","o":["is","are"],"a":1},{"t":"choice","q":"There ___ two chairs.","o":["is","are"],"a":1},{"t":"choice","q":"<span class='en'>Is there a ladder?</span>","h":"Respondé que SÍ","o":["Yes, there is.","Yes, there are.","Yes, it is."],"a":0},{"t":"choice","q":"<span class='en'>Are there any stairs?</span>","h":"Respondé que NO","o":["No, there isn't.","No, there aren't.","No, they aren't."],"a":1},{"t":"choice","q":"<span class='en'>How many chairs are there?</span>","h":"Hay 6","o":["There is six.","There are six.","They are six."],"a":1},{"t":"choice","e":"🐱📦","q":"El gato está <b>ADENTRO</b> de la caja.","o":["The cat is in the box.","The cat is on the box.","The cat is under the box."],"a":0},{"t":"choice","q":"El perro está <b>DEBAJO</b> de la mesa.","o":["behind the table","under the table","next to the table"],"a":1},{"t":"choice","q":"La pelota está <b>ENTRE</b> las dos sillas.","o":["in front of the chairs","behind the chairs","between the chairs"],"a":2},{"t":"choice","q":"La lámpara está <b>AL LADO</b> de la cama.","o":["next to the bed","under the bed","on the bed"],"a":0},{"t":"choice","q":"El cuadro está <b>DETRÁS</b> del sofá.","o":["in front of the sofa","behind the sofa","on the sofa"],"a":1},{"t":"match","q":"Uní cada habitación con su nombre","pairs":[["kitchen","cocina"],["bathroom","baño"],["bedroom","dormitorio"],["dining room","comedor"],["living room","living"]]},{"t":"choice","q":"¿En qué habitación cocinás?","o":["in the bathroom","in the kitchen","in the hall"],"a":1},{"t":"spell","q":"Escribí en inglés: <b>sillón</b>","a":"armchair"},{"t":"spell","q":"Escribí en inglés: <b>reloj</b>","a":"clock"},{"t":"match","q":"Uní cada mueble con su nombre","pairs":[["table","mesa"],["phone","teléfono"],["picture","cuadro"],["radio","la radio"],["television","televisión"],["sofa","sofá"]]},{"t":"choice","q":"<span class='en'>Where is the phone?</span>","h":"Está ARRIBA de la mesa","o":["It's on the table.","It's in the table.","It's under the table."],"a":0}]},{"id":"u4","dot":"🧸","name":"Unit 4","title":"Unit 4","sub":"I like / He likes · juguetes · el dormitorio","rules":"\n<div class=\"rsec\"><h4>La S de he / she / it</h4>\n<div class=\"rrow\"><span class=\"rl\">I / you / we / they</span><span class=\"ra\">like</span></div>\n<div class=\"rrow\"><span class=\"rl\">he / she / it</span><span class=\"ra\">like<b>s</b></span></div>\n<p class=\"exline\">My cousin <b>likes</b> music. &nbsp; We <b>like</b> music.</p></div>\n<div class=\"rsec\"><h4>El negativo</h4>\n<div class=\"rrow\"><span class=\"rl\">I / you / we / they</span><span class=\"ra\">don't</span></div>\n<div class=\"rrow\"><span class=\"rl\">he / she / it</span><span class=\"ra\">doesn't</span></div>\n<p class=\"exline\">We <b>don't</b> like rain. &nbsp; It <b>doesn't</b> like water.</p></div>\n<div class=\"rsec\"><h4>La pregunta</h4>\n<div class=\"rrow\"><span class=\"rl\">Do they like school?</span><span class=\"ra\">Yes, they do. / No, they don't.</span></div>\n<div class=\"rrow\"><span class=\"rl\">Does your dad like tea?</span><span class=\"ra\">Yes, he does. / No, he doesn't.</span></div></div>\n<div class=\"rsec\"><h4>&#11088; La regla más importante de la unidad</h4>\n<div class=\"warn\"><b>La S aparece UNA sola vez por frase.</b> Si ya está en <b>does</b> o <b>doesn't</b>, el verbo va limpio.<br><br>\n<span class=\"yes\">&#10003;</span> She play<b>s</b> tennis.<br>\n<span class=\"yes\">&#10003;</span> She <b>doesn't play</b> tennis. &nbsp; <span class=\"no\">&#10007;</span> She doesn't <span class=\"no\">plays</span>.<br>\n<span class=\"yes\">&#10003;</span> <b>Does</b> she <b>play</b> tennis? &nbsp; <span class=\"no\">&#10007;</span> Does she <span class=\"no\">plays</span>?<br><br>\n<b>Truco:</b> \"does le roba la S al verbo\".</div></div>","ex":[{"t":"choice","q":"I ___ dolls. 😍","o":["like","likes"],"a":0},{"t":"choice","q":"He ___ robots. 😍","o":["like","likes"],"a":1},{"t":"choice","q":"She ___ like trucks. 🙅","o":["don't","doesn't"],"a":1},{"t":"choice","q":"I ___ like trains. 🙅","o":["don't","doesn't"],"a":0},{"t":"choice","q":"<span class='en'>Do you like monsters?</span>","h":"Respondé que SÍ","o":["Yes, I do.","Yes, I like.","Yes, I does."],"a":0},{"t":"choice","q":"<span class='en'>Does she like teddy bears?</span>","h":"Respondé que NO","o":["No, she don't.","No, she doesn't.","No, she isn't."],"a":1},{"t":"choice","q":"___ he like cars?","o":["Do","Does"],"a":1},{"t":"choice","q":"___ you like dolls?","o":["Do","Does"],"a":0},{"t":"match","q":"Uní cada juguete con su significado","pairs":[["ball","pelota"],["doll","muñeca"],["teddy bear","osito"],["truck","camión"],["bike","bicicleta"],["boat","barco"]]},{"t":"choice","e":"🛏️","q":"¿Dónde dormís?","o":["in the bed","on the desk","on the rug"],"a":0},{"t":"spell","q":"Escribí en inglés: <b>ventana</b>","a":"window"},{"t":"spell","q":"Escribí en inglés: <b>espejo</b>","a":"mirror"},{"t":"spell","q":"Escribí en inglés: <b>lámpara</b>","a":"lamp"},{"t":"match","q":"Uní cada cosa del dormitorio","pairs":[["bookcase","biblioteca"],["door","puerta"],["wall","pared"],["desk","escritorio"],["rug","alfombra"],["bed","cama"]]}]},{"id":"u5","dot":"🐴","name":"Unit 5","title":"Unit 5","sub":"Can · animales de granja · comida","rules":"\n<div class=\"rsec\"><h4>CAN es igual para todos</h4>\n<p class=\"exline\">No cambia nunca y <b>no lleva S</b>, ni siquiera con he / she / it.</p>\n<div class=\"rrow\"><span class=\"rl\">My brother <b>can</b> dance.</span><span class=\"ra\">nunca \"cans\"</span></div>\n<p class=\"exline\">El verbo que viene después va <b>solo</b>, sin \"to\": can <b>jump</b>, can <b>sing</b>.</p></div>\n<div class=\"rsec\"><h4>Negativo y pregunta con CAN</h4>\n<div class=\"rrow\"><span class=\"rl\">negativo</span><span class=\"ra\">can't</span></div>\n<div class=\"rrow\"><span class=\"rl\">Can it climb?</span><span class=\"ra\">Yes, it can. / No, it can't.</span></div></div>\n<div class=\"rsec\"><h4>Hechos: lo que pasa siempre</h4>\n<div class=\"rrow\"><span class=\"rl\">plural (varios)</span><span class=\"ra\">Cats sleep a lot.</span></div>\n<div class=\"rrow\"><span class=\"rl\">singular (uno)</span><span class=\"ra\">A cat sleep<b>s</b> a lot.</span></div>\n<p class=\"exline\">Es la misma S de la Unit 4. Para preguntar se usan <b>Do</b> y <b>Does</b>, con la misma división.</p></div>\n<div class=\"rsec\"><h4>&#9888; No mezclar CAN con DO</h4>\n<div class=\"warn\">La respuesta corta repite el verbo con el que <b>empieza</b> la pregunta.<br>\nCan you dance? &rarr; <span class=\"yes\">Yes, I can</span>, nunca <span class=\"no\">Yes, I do</span>.<br>\nDo you dance? &rarr; <span class=\"yes\">Yes, I do</span>, nunca <span class=\"no\">Yes, I can</span>.</div></div>","ex":[{"t":"choice","e":"🐦","q":"Birds ___ fly.","o":["can","can't"],"a":0},{"t":"choice","e":"🐴","q":"Horses ___ fly.","o":["can","can't"],"a":1},{"t":"choice","q":"<span class='en'>Can you swim?</span>","h":"Respondé que SÍ","o":["Yes, I can.","Yes, I do.","Yes, I am."],"a":0},{"t":"choice","q":"<span class='en'>Can you fly?</span>","h":"Respondé que NO","o":["No, I don't.","No, I can't.","No, I am not."],"a":1},{"t":"choice","q":"Horses ___ grass.","o":["eat","eats"],"a":0},{"t":"choice","q":"<span class='en'>Do they eat meat?</span>","h":"Los caballos NO comen carne","o":["No, they don't.","No, they aren't.","No, they can't."],"a":0},{"t":"choice","q":"<span class='en'>Do we eat carrots?</span>","h":"Respondé que SÍ","o":["Yes, we can.","Yes, we do.","Yes, we are."],"a":1},{"t":"match","q":"Uní cada animal con su nombre","pairs":[["cow","vaca"],["duck","pato"],["sheep","oveja"],["goat","cabra"],["donkey","burro"],["chicken","gallina"]]},{"t":"choice","e":"🍉","q":"<span class='en'>What is it?</span>","o":["It's a watermelon.","It's a lettuce.","It's corn."],"a":0},{"t":"choice","e":"🐰🥕","q":"Rabbits eat ___.","o":["meat","bread","carrots"],"a":2},{"t":"choice","q":"El elefante es muy ___.","o":["strong","tired","smart"],"a":0},{"t":"spell","q":"Escribí en inglés: <b>maíz</b>","a":"corn"},{"t":"spell","q":"Escribí en inglés: <b>pan</b>","a":"bread"},{"t":"match","q":"Uní cada comida con su nombre","pairs":[["apples","manzanas"],["tomatoes","tomates"],["bread","pan"],["lettuce","lechuga"],["watermelons","sandías"],["corn","maíz"]]},{"t":"choice","e":"🍌","q":"<span class='en'>What is it?</span>","o":["It's a banana.","It's an apple.","It's corn."],"a":0}]},{"id":"u6","dot":"🐞","name":"Unit 6","title":"Unit 6","sub":"Have got · this/that/these/those · el cuerpo","rules":"\n<div class=\"rsec\"><h4>HAVE GOT = tener</h4>\n<p class=\"exline\">Son <b>dos palabras que van siempre juntas</b> y significan una sola cosa: tener.</p>\n<div class=\"rrow\"><span class=\"rl\">I / you / we / they</span><span class=\"ra\">have got</span></div>\n<div class=\"rrow\"><span class=\"rl\">he / she / it</span><span class=\"ra\">has got</span></div>\n<p class=\"exline\">I <b>have got</b> two brothers. &nbsp; My friend <b>has got</b> a bike.</p></div>\n<div class=\"rsec\"><h4>&#11088; \"GOT\" no cambia nunca</h4>\n<div class=\"warn\">Lo único que se mueve es <b>have</b> / <b>has</b>. La palabra <b>got</b> se escribe siempre igual.<br>\nNo existen <span class=\"no\">\"hases\"</span>, <span class=\"no\">\"gots\"</span> ni <span class=\"no\">\"haves\"</span>.</div></div>\n<div class=\"rsec\"><h4>Negativo, pregunta y respuesta corta</h4>\n<div class=\"rrow\"><span class=\"rl\">negativo</span><span class=\"ra\">haven't got / hasn't got</span></div>\n<div class=\"rrow\"><span class=\"rl\">Has she got a sister?</span><span class=\"ra\">Yes, she has. / No, she hasn't.</span></div>\n<div class=\"warn\"><b>&#9888; En la respuesta corta NO se repite \"got\".</b><br>\n<span class=\"yes\">&#10003;</span> Yes, they <b>have</b>. &nbsp;&nbsp; <span class=\"no\">&#10007;</span> Yes, they have <span class=\"no\">got</span>.</div></div>\n<div class=\"rsec\"><h4>This / That / These / Those</h4>\n<div class=\"rrow\"><span class=\"rl\">cerca — 1</span><span class=\"ra\">this</span></div>\n<div class=\"rrow\"><span class=\"rl\">cerca — varios</span><span class=\"ra\">these</span></div>\n<div class=\"rrow\"><span class=\"rl\">lejos — 1</span><span class=\"ra\">that</span></div>\n<div class=\"rrow\"><span class=\"rl\">lejos — varios</span><span class=\"ra\">those</span></div>\n<p class=\"exline\"><b>This</b> is a book. &nbsp; <b>These</b> are books. &nbsp; <b>That</b> is a tree. &nbsp; <b>Those</b> are trees.</p>\n<div class=\"warn\"><b>Truco:</b> <b>these</b> y <b>those</b> terminan en <b>-se</b> &rarr; son los plurales. Y si la palabra es plural, el verbo también: These <b>are</b>, Those <b>are</b>.</div></div>","ex":[{"t":"choice","q":"I ___ got a dog.","o":["have","has"],"a":0},{"t":"choice","q":"A snake ___ got any legs. 🐍","o":["haven't","hasn't"],"a":1},{"t":"choice","q":"<span class='en'>Have you got any lizards?</span>","h":"Respondé que SÍ","o":["Yes, I have.","Yes, I has.","Yes, I am."],"a":0},{"t":"choice","q":"<span class='en'>Has it got any legs?</span>","h":"Respondé que NO","o":["No, it haven't.","No, it hasn't.","No, it isn't."],"a":1},{"t":"choice","q":"___ this a spider?","o":["Is","Are"],"a":0},{"t":"choice","q":"___ these butterflies?","o":["Is","Are"],"a":1},{"t":"choice","e":"🐝🐝","q":"Cerca y en plural: ___ are bees.","o":["This","These","That"],"a":1},{"t":"choice","e":"🦋🦋","q":"Lejos y en plural: ___ are butterflies.","o":["These","That","Those"],"a":2},{"t":"choice","e":"🐭","q":"Cerca y singular: ___ is a mouse.","o":["This","These","Those"],"a":0},{"t":"choice","q":"¿Cómo preguntás por varias cosas?","o":["What is these?","What are these?","What are this?"],"a":1},{"t":"match","q":"Uní cada bichito con su nombre","pairs":[["bee","abeja"],["frog","rana"],["spider","araña"],["butterfly","mariposa"],["ladybug","vaquita de San Antonio"],["caterpillar","oruga"]]},{"t":"match","q":"Uní cada parte del cuerpo","pairs":[["head","cabeza"],["hand","mano"],["leg","pierna"],["mouth","boca"],["ear","oreja"],["nose","nariz"]]},{"t":"choice","q":"El plural de <span class='en'>foot</span> es:","o":["foots","feet","footes"],"a":1},{"t":"spell","q":"Escribí en inglés: <b>ojo</b>","a":"eye"},{"t":"spell","q":"Escribí en inglés: <b>pelo</b>","a":"hair"},{"t":"spell","q":"Escribí en inglés: <b>brazo</b>","a":"arm"}]},{"id":"n1","dot":"🏃","name":"Ahora mismo","title":"Present continuous","sub":"What are you doing? · lo que pasa ahora","rules":"\n<div class=\"rsec\"><h4>Algo nuevo: lo que pasa ahora</h4>\n<p class=\"exline\">Hasta ahora sabía decir lo que pasa <b>siempre</b>. Se agrega decir lo que pasa <b>ahora mismo</b>.</p>\n<div class=\"rrow\"><span class=\"rl\">Todos los días</span><span class=\"ra\">I jump.</span></div>\n<div class=\"rrow\"><span class=\"rl\">En este momento</span><span class=\"ra\">I'm jumping.</span></div></div>\n<div class=\"rsec\"><h4>Cómo se arma: TO BE + verbo con -ING</h4>\n<div class=\"rrow\"><span class=\"rl\">I</span><span class=\"ra\">am + …ing</span></div>\n<div class=\"rrow\"><span class=\"rl\">he / she / it</span><span class=\"ra\">is + …ing</span></div>\n<div class=\"rrow\"><span class=\"rl\">you / we / they</span><span class=\"ra\">are + …ing</span></div>\n<div class=\"warn\"><b>&#9888; Siempre van las DOS partes.</b> No alcanza con el -ing solo.<br>\n<span class=\"yes\">&#10003;</span> She<b>'s</b> drawing. &nbsp;&nbsp; <span class=\"no\">&#10007;</span> She drawing.</div></div>\n<div class=\"rsec\"><h4>Dos trampas al agregar -ING</h4>\n<div class=\"rrow\"><span class=\"rl\">swim &rarr; swi<b>mm</b>ing</span><span class=\"ra\">se dobla la consonante final</span></div>\n<div class=\"rrow\"><span class=\"rl\">make &rarr; mak<b>ing</b></span><span class=\"ra\">se cae la E final</span></div>\n<p class=\"exline\">La mayoría son directos: solo se agrega <b>-ing</b> sin tocar nada.</p>\n<div class=\"warn\">¿Cuándo se dobla? Cuando el verbo es corto y termina en <b>una vocal + una consonante</b>. ¿Cuándo se cae la E? Cuando el verbo termina en <b>-e</b> muda.</div></div>\n<div class=\"rsec\"><h4>El imperativo</h4>\n<p class=\"exline\">Las órdenes van con el <b>verbo solo</b> al principio, sin sujeto adelante.</p></div>","ex":[{"t":"choice","q":"<span class='en'>What are you doing?</span>","h":"Estás haciendo Matemática","o":["I'm doing Maths.","I do Maths.","I doing Maths."],"a":0},{"t":"choice","q":"She ___ playing football.","o":["am","is","are"],"a":1},{"t":"choice","q":"They ___ reading.","o":["is","are"],"a":1},{"t":"choice","q":"I ___ eating an apple.","o":["am","is","are"],"a":0},{"t":"fill","q":"Escribí el verbo con -ING","labels":["play","read","eat","sing"],"a":["playing","reading","eating","singing"]},{"t":"fill","q":"Cuidado con estos dos","labels":["run","write"],"a":["running","writing"]},{"t":"choice","q":"<b>Ahora mismo</b> estoy comiendo.","o":["I eat.","I'm eating."],"a":1},{"t":"choice","q":"<b>Todos los días</b> como fruta.","o":["I eat fruit.","I'm eating fruit."],"a":0},{"t":"choice","q":"«Sentate, por favor» en inglés es:","o":["Sit down, please.","You sit down.","I sit down."],"a":0,"why":"Las órdenes van con el verbo solo al principio, sin sujeto."}]},{"id":"n2","dot":"📅","name":"Días y clima","title":"Días, meses, cumpleaños y clima","sub":"When's your birthday? · What's the weather like?","rules":"\n<div class=\"rsec\"><h4>Mayúscula obligatoria</h4>\n<div class=\"warn\">En inglés los <b>días</b> y los <b>meses</b> se escriben SIEMPRE con mayúscula, aunque estén en el medio de la oración. En castellano no: ahí está el error típico.</div></div>\n<div class=\"rsec\"><h4>Las preposiciones de tiempo</h4>\n<div class=\"rrow\"><span class=\"rl\">con un mes</span><span class=\"ra\">IN</span></div>\n<div class=\"rrow\"><span class=\"rl\">con un día</span><span class=\"ra\">ON</span></div>\n<p class=\"exline\">My birthday is <b>in</b> May. &nbsp; <b>On</b> Sundays we go to the park.</p>\n<div class=\"warn\"><b>Regla corta:</b> cuanto más grande el período de tiempo, más \"adentro\" estás: por eso el mes lleva <b>in</b> y el día, que es más puntual, lleva <b>on</b>.</div></div>\n<div class=\"rsec\"><h4>El clima se dice con IT</h4>\n<p class=\"exline\">No se usa <i>there is</i> ni un sujeto real: el clima siempre arranca con <b>It's</b>.</p>\n<div class=\"rrow\"><span class=\"rl\">What's the weather like?</span><span class=\"ra\">It's cold.</span></div>\n<div class=\"warn\"><b>&#9888;</b> Muchas palabras del clima terminan en <b>-y</b>. Si la escribís sin esa terminación, estás nombrando la cosa y no el estado del tiempo.</div></div>","ex":[{"t":"match","q":"Uní cada día con su nombre","pairs":[["Monday","lunes"],["Tuesday","martes"],["Wednesday","miércoles"],["Thursday","jueves"],["Friday","viernes"],["Saturday","sábado"],["Sunday","domingo"]]},{"t":"match","q":"Uní cada mes con su nombre","pairs":[["January","enero"],["March","marzo"],["June","junio"],["July","julio"],["September","septiembre"],["December","diciembre"]]},{"t":"choice","q":"Hoy es jueves. <span class='en'>Tomorrow is ___.</span>","o":["Wednesday","Friday","Saturday"],"a":1},{"t":"choice","q":"<span class='en'>When's your birthday?</span>","h":"En julio","o":["It's in July.","It's on July.","I'm July."],"a":0},{"t":"choice","q":"<span class='en'>___ Mondays I play football.</span>","o":["In","On","At"],"a":1},{"t":"match","q":"Uní cada palabra del clima","pairs":[["sunny","soleado"],["cloudy","nublado"],["rainy","lluvioso"],["windy","ventoso"],["snowy","con nieve"],["hot","caluroso"]]},{"t":"choice","q":"<span class='en'>What's the weather like today?</span>","h":"Está nublado","o":["It's cloudy.","There is cloudy.","It's cloud."],"a":0},{"t":"fill","q":"Escribí el día en inglés (con mayúscula)","labels":["sábado","miércoles"],"a":["saturday","wednesday"]}]},{"id":"n3","dot":"🏙️","name":"La ciudad","title":"La ciudad, la ropa y las acciones","sub":"There is / There are · preposiciones · I'm wearing · can","rules":"\n<div class=\"rsec\"><h4>There is / There are en la ciudad</h4>\n<p class=\"exline\">Funciona igual que en la Unit 3 (la casa). Lo único que cambia es el vocabulario: ahora se habla de la ciudad.</p>\n<div class=\"rrow\"><span class=\"rl\">Is there a hospital? (no)</span><span class=\"ra\">No, there isn't.</span></div>\n<div class=\"rrow\"><span class=\"rl\">Are there any buses? (sí)</span><span class=\"ra\">Yes, there are.</span></div></div>\n<div class=\"rsec\"><h4>BETWEEN necesita AND</h4>\n<p class=\"exline\">\"Entre A y B\" se arma siempre igual: <b>between</b> + una referencia + <b>and</b> + la otra.</p>\n<div class=\"warn\">Si hay una sola referencia, no puede ser <i>between</i>: ahí va otra preposición.</div></div>\n<div class=\"rsec\"><h4>A o AN</h4>\n<div class=\"rrow\"><span class=\"rl\">empieza con consonante</span><span class=\"ra\">a dog</span></div>\n<div class=\"rrow\"><span class=\"rl\">empieza con vocal</span><span class=\"ra\">an elephant</span></div>\n<p class=\"exline\">Se mira la <b>primera letra de la palabra que sigue</b>, no la del sustantivo principal.</p></div>\n<div class=\"rsec\"><h4>CAN y DO no se mezclan</h4>\n<p class=\"exline\">La respuesta corta repite el verbo con el que empieza la pregunta. Es la misma regla de la Unit 5.</p></div>","ex":[{"t":"choice","q":"<span class='en'>Is there a park?</span>","h":"Respondé que SÍ","o":["Yes, there is.","Yes, it is.","Yes, there are."],"a":0},{"t":"choice","q":"<span class='en'>Are there any shops?</span>","h":"Respondé que NO","o":["No, there isn't.","No, there aren't.","No, they aren't."],"a":1},{"t":"choice","q":"The supermarket is ___ the bank ___ the post office.","o":["between / and","next to / and","in / on"],"a":0},{"t":"match","q":"Uní cada lugar de la ciudad","pairs":[["supermarket","supermercado"],["bank","banco"],["post office","correo"],["park","plaza"],["shop","negocio"],["school","escuela"]]},{"t":"choice","q":"<span class='en'>The picture is ___ the sofa.</span>","h":"Está ARRIBA del sofá","o":["in","on","under"],"a":1},{"t":"match","q":"Uní cada prenda de ropa","pairs":[["hat","gorro"],["shoes","zapatos"],["T-shirt","remera"],["trousers","pantalón"],["jacket","campera"],["dress","vestido"]]},{"t":"choice","q":"<span class='en'>I'm wearing ___ hat.</span>","o":["a","an","the"],"a":0},{"t":"choice","q":"<span class='en'>I'm eating ___ apple.</span>","o":["a","an"],"a":1,"why":"Apple empieza con vocal, así que va AN."},{"t":"choice","q":"<span class='en'>I can run but I ___ rollerblade.</span>","o":["don't","can't","am not"],"a":1},{"t":"choice","q":"<span class='en'>Do you like pizza?</span>","h":"Respondé que SÍ","o":["Yes, I do.","Yes, I like.","Yes, I am."],"a":0}]},{"id":"n4","dot":"👩‍🏫","name":"It y posesión","title":"It, demostrativos, posesión y profesiones","sub":"It is a ball · Those are my cars · I've got","rules":"\n<div class=\"rsec\"><h4>IT: para objetos y animales</h4>\n<p class=\"exline\">Las personas son <b>he</b> o <b>she</b>. Todo lo demás —objetos, animales, el clima— es <b>it</b>.</p>\n<div class=\"rrow\"><span class=\"rl\">un árbol</span><span class=\"ra\">It is a tree.</span></div></div>\n<div class=\"rsec\"><h4>Demostrativos</h4>\n<div class=\"rrow\"><span class=\"rl\">cerca — 1</span><span class=\"ra\">this</span></div>\n<div class=\"rrow\"><span class=\"rl\">cerca — varios</span><span class=\"ra\">these</span></div>\n<div class=\"rrow\"><span class=\"rl\">lejos — 1</span><span class=\"ra\">that</span></div>\n<div class=\"rrow\"><span class=\"rl\">lejos — varios</span><span class=\"ra\">those</span></div>\n<p class=\"exline\"><b>This</b> is a pen. &nbsp; <b>These</b> are pens. &nbsp; <b>That</b> is a house. &nbsp; <b>Those</b> are houses.</p>\n<div class=\"warn\"><b>Dos preguntas antes de elegir:</b> ¿está cerca o lejos? ¿es uno o son varios? Con esas dos respuestas sale solo.</div></div>\n<div class=\"rsec\"><h4>Posesión con HAVE GOT</h4>\n<div class=\"rrow\"><span class=\"rl\">I / you / we / they</span><span class=\"ra\">have got · haven't got</span></div>\n<div class=\"rrow\"><span class=\"rl\">he / she / it</span><span class=\"ra\">has got · hasn't got</span></div>\n<p class=\"exline\">I've got a sister. &nbsp; She hasn't got a pet.</p>\n<div class=\"warn\">En la respuesta corta <b>no se repite \"got\"</b>: Yes, I have / No, she hasn't.</div></div>\n<div class=\"rsec\"><h4>HIS o HER</h4>\n<p class=\"exline\">Depende del <b>dueño</b>, no de la cosa. Si el dueño es varón, <b>his</b>; si es mujer, <b>her</b>.</p></div>","ex":[{"t":"choice","q":"Para un objeto o un animal usamos:","o":["he","she","it"],"a":2},{"t":"choice","e":"⚽","q":"___ is a ball.","o":["He","She","It"],"a":2},{"t":"choice","q":"Lejos y en plural: ___ are my cars.","o":["These","Those","That"],"a":1},{"t":"choice","q":"Cerca y en singular: ___ is my cat.","o":["This","These","Those"],"a":0},{"t":"choice","q":"<span class='en'>I ___ got a ball.</span>","h":"NO tengo","o":["haven't","hasn't"],"a":0},{"t":"choice","q":"<span class='en'>He ___ got a dog.</span>","h":"NO tiene","o":["haven't","hasn't"],"a":1},{"t":"choice","q":"<span class='en'>Has he got a bike?</span>","h":"Respondé que SÍ","o":["Yes, he has.","Yes, he have.","Yes, he is."],"a":0},{"t":"choice","q":"This is Ben. This is ___ hat.","o":["his","her","its"],"a":0},{"t":"match","q":"Uní cada profesión","pairs":[["teacher","maestro/a"],["doctor","médico/a"],["zoo keeper","cuidador del zoo"],["firefighter","bombero"],["vet","veterinario/a"],["police officer","policía"]]},{"t":"match","q":"Uní cada materia escolar","pairs":[["Maths","Matemática"],["English","Inglés"],["Art","Plástica"],["Music","Música"],["PE","Educación Física"],["Science","Ciencias"]]},{"t":"match","q":"Uní cada emoción","pairs":[["happy","contento"],["sad","triste"],["angry","enojado"],["scared","asustado"],["tired","cansado"],["hungry","con hambre"]]},{"t":"choice","q":"<span class='en'>I can see elephants and ___.</span>","h":"tigres","o":["tigers","tigres","tigrs"],"a":0}]},{"id":"resumen","dot":"U0001F4CB","name":"Resumen","title":"Resumen general","sub":"¿Cuándo uso cada uno? — la chuleta final","rules":"\n<div class=\"rsec\"><h4>1. ¿Qué querés decir?</h4>\n<div class=\"rrow\"><span class=\"rl\">ser, estar, edad, cómo es algo</span><span class=\"ra\">am / is / are</span></div>\n<div class=\"rrow\"><span class=\"rl\">tener algo</span><span class=\"ra\">have got / has got</span></div>\n<div class=\"rrow\"><span class=\"rl\">gustar, comer, acciones y hechos</span><span class=\"ra\">do / does</span></div>\n<div class=\"rrow\"><span class=\"rl\">poder o saber hacer</span><span class=\"ra\">can</span></div>\n<div class=\"rrow\"><span class=\"rl\">hay cosas en un lugar</span><span class=\"ra\">there is / there are</span></div></div>\n<div class=\"rsec\"><h4>2. ¿Quién hace la acción? Hay dos grupos</h4>\n<div class=\"rrow\"><span class=\"rl\"><b>Grupo A</b> — I, you, we, they</span><span class=\"ra\">are · have got · like · do</span></div>\n<div class=\"rrow\"><span class=\"rl\"><b>Grupo B</b> — he, she, it</span><span class=\"ra\">is · has got · likes · does</span></div>\n<div class=\"warn\"><b>El Grupo B es el de la S:</b> i<b>s</b>, ha<b>s</b>, like<b>s</b>, doe<b>s</b>. Si el sujeto es él, ella, un animal o una cosa, casi todo lleva S.<br>\n(<b>I</b> es la excepción: va con <b>am</b>.)</div></div>\n<div class=\"rsec\"><h4>3. Las respuestas cortas repiten el verbo de la pregunta</h4>\n<p class=\"exline\">Mirá con qué palabra <b>empieza</b> la pregunta y contestá con esa misma:</p>\n<div class=\"rrow\"><span class=\"rl\">Is… / Are… / Am…</span><span class=\"ra\">… is / are / am</span></div>\n<div class=\"rrow\"><span class=\"rl\">Do… / Does…</span><span class=\"ra\">… do / does</span></div>\n<div class=\"rrow\"><span class=\"rl\">Have… / Has…</span><span class=\"ra\">… have / has</span></div>\n<div class=\"rrow\"><span class=\"rl\">Can…</span><span class=\"ra\">… can</span></div>\n<div class=\"warn\"><b>&#9888; El error más común de toda la prueba</b> es contestar con el verbo equivocado. Antes de responder, tapá la pregunta con el dedo salvo la primera palabra: esa manda.</div></div>","ex":[]}]},{"id":"mate","name":"Matemática","emo":"🔢","tag":"","desc":"Números, series, cuentas y problemas","c1":"#3F8FE8","c2":"#4FB9DB","units":[{"id":"m1","dot":"🔢","name":"Día 1","title":"Día 1 · Números y valor posicional","sub":"Leer, escribir, descomponer y comparar","rules":"\n<div class=\"rsec\"><h4>Valor posicional</h4>\n<p class=\"exline\">En <b>487</b> cada cifra vale distinto según el lugar que ocupa:</p>\n<div class=\"rrow\"><span class=\"rl\">el 4 está en las <b>centenas</b></span><span class=\"ra\">vale 400</span></div>\n<div class=\"rrow\"><span class=\"rl\">el 8 está en las <b>decenas</b></span><span class=\"ra\">vale 80</span></div>\n<div class=\"rrow\"><span class=\"rl\">el 7 está en las <b>unidades</b></span><span class=\"ra\">vale 7</span></div>\n<p class=\"exline\">Descomponer es escribirlo así: <b>487 = 400 + 80 + 7</b>.</p>\n<div class=\"warn\"><b>&#9888; Cuidado con los ceros.</b> Si una posición tiene 0, esa parte <b>no se escribe</b>: en 306 no hay decenas, así que la descomposición tiene solo dos partes, no tres.</div></div>\n<div class=\"rsec\"><h4>Comparar: &lt; y &gt;</h4>\n<p class=\"exline\">La boca del signo <b>siempre se abre hacia el número más grande</b>.</p>\n<div class=\"rrow\"><span class=\"rl\">271 &lt; 294</span><span class=\"ra\">la boca mira a 294</span></div>\n<div class=\"rrow\"><span class=\"rl\">530 &gt; 503</span><span class=\"ra\">la boca mira a 530</span></div>\n<div class=\"warn\"><b>Cómo comparar en dos pasos:</b><br>\n1. Contá cuántas cifras tiene cada uno. El que tiene más, gana: <b>102 &gt; 88</b> aunque empiece con 1.<br>\n2. Si tienen la misma cantidad, compará cifra por cifra <b>desde la izquierda</b>, hasta encontrar la primera diferencia.</div></div>\n<div class=\"rsec\"><h4>Ordenar de menor a mayor</h4>\n<p class=\"exline\">Separá primero por cantidad de cifras: van antes los de dos cifras, después los de tres, después los de cuatro. Recién dentro de cada grupo comparás.</p></div>","ex":[{"t":"fill","q":"Escribí con palabras","labels":["126","408","735","1.204"],"a":["ciento veintiseis","cuatrocientos ocho","setecientos treinta y cinco","mil doscientos cuatro"]},{"t":"fill","q":"Escribí el número en cifras","labels":["Doscientos treinta y cinco","Seiscientos ocho","Mil trescientos veinte","Novecientos noventa y nueve"],"a":["235","608","1320","999"]},{"t":"fill","q":"Descomponé el número","viz":{"k":"base10","c":1,"d":2,"u":6},"h":"El dibujo muestra 126. Ejemplo: 426 = 400 + 20 + 6","labels":["583 =","709 =","1.346 =","2.080 ="],"a":["500+80+3","700+9","1000+300+40+6","2000+80"],"why":"Ojo con el 709: no hay decenas, así que va 700 + 9."},{"t":"choice","q":"345 ___ 354","o":["&lt;","&gt;","="],"a":0},{"t":"choice","q":"809 ___ 790","o":["&lt;","&gt;","="],"a":1},{"t":"choice","q":"1.205 ___ 1.250","o":["&lt;","&gt;","="],"a":0},{"t":"choice","q":"999 ___ 1.000","o":["&lt;","&gt;","="],"a":0,"why":"999 tiene 3 cifras y 1.000 tiene 4. El que tiene más cifras es mayor."},{"t":"choice","q":"632 ___ 632","o":["&lt;","&gt;","="],"a":2},{"t":"order","q":"Ordená de menor a mayor","h":"Tocá los números en orden, del más chico al más grande","items":["508","85","580","805","358"],"a":["85","358","508","580","805"]}]},{"id":"m2","dot":"📈","name":"Día 2","title":"Día 2 · Series y relaciones","sub":"Regularidades, anterior y siguiente, 100 más y 100 menos","rules":"\n<div class=\"rsec\"><h4>¿Qué es una regularidad?</h4>\n<p class=\"exline\">Es algo que se repite siguiendo una regla. Para descubrirla, mirá <b>cuánto cambia de un número al siguiente</b>.</p>\n<div class=\"rrow\"><span class=\"rl\">300 – 400 – 500</span><span class=\"ra\">+100 cada vez</span></div>\n<div class=\"rrow\"><span class=\"rl\">90 – 80 – 70</span><span class=\"ra\">−10 cada vez</span></div>\n<div class=\"warn\"><b>&#9888; Primero fijate si sube o baja.</b> Muchos errores salen de sumar en una serie que en realidad va restando. Restá dos números seguidos para encontrar el salto.</div></div>\n<div class=\"rsec\"><h4>Sumar o restar 100 y 1.000</h4>\n<p class=\"exline\">Normalmente cambia <b>una sola cifra</b>:</p>\n<div class=\"rrow\"><span class=\"rl\">100 más que <b>7</b>12</span><span class=\"ra\"><b>8</b>12</span></div>\n<div class=\"rrow\"><span class=\"rl\">1.000 más que <b>5</b>.040</span><span class=\"ra\"><b>6</b>.040</span></div>\n<div class=\"warn\"><b>&#9888; La excepción:</b> cuando hay que \"pasarse\", cambian varias cifras a la vez. Uno menos que <b>400</b> no es 309 ni 390: es <b>399</b>. Pensalo como bajar un escalón entero.</div></div>\n<div class=\"rsec\"><h4>El número del medio</h4>\n<p class=\"exline\">Entre dos números que se llevan por 2, el del medio es el que sigue al primero. Entre 120 y 122 está el 121.</p></div>","ex":[{"t":"fill","q":"Completá la serie: 120 – 130 – 140 – ...","viz":{"k":"numline","from":120,"to":170,"step":10,"marks":[120,130,140],"q":150},"labels":["","",""],"a":["150","160","170"],"why":"Va de 10 en 10."},{"t":"fill","q":"Completá la serie: 450 – 400 – 350 – ...","labels":["",""],"a":["300","250"],"why":"Esta BAJA de 50 en 50."},{"t":"fill","q":"Completá la serie: 205 – 210 – 215 – ...","labels":["",""],"a":["220","225"],"why":"Va de 5 en 5."},{"t":"fill","q":"Completá la serie: 1.000 – 2.000 – 3.000 – ...","labels":["",""],"a":["4000","5000"],"why":"Va de 1.000 en 1.000."},{"t":"fill","q":"Escribí el número que corresponde","labels":["Uno más que 459","Uno menos que 700","100 más que 325","100 menos que 840","1.000 más que 2.315","1.000 menos que 4.600"],"a":["460","699","425","740","3315","3600"]},{"t":"fill","q":"¿Qué número está justo en el medio?","viz":{"k":"numline","from":346,"to":352,"marks":[348,350],"q":349},"labels":["Entre 348 y 350","Entre 1.199 y 1.201","Entre 699 y 701"],"a":["349","1200","700"]},{"t":"fill","q":"Escribí dos números entre 620 y 630","labels":["",""],"a":["re:^62[1-9]$","re:^62[1-9]$"],"why":"Cualquiera del 621 al 629 sirve."},{"t":"fill","q":"Descubrí la regla y continuá: 7 – 14 – 21 – 28 – ...","labels":["",""],"a":["35","42"],"why":"Va de 7 en 7. Es la tabla del 7."}]},{"id":"m3","dot":"➕","name":"Día 3","title":"Día 3 · Sumas y restas","sub":"Cálculo mental, cuentas paradas y descomposición","rules":"\n<div class=\"rsec\"><h4>Tres formas de resolver</h4>\n<div class=\"rrow\"><span class=\"rl\">Mentalmente</span><span class=\"ra\">150 + 20 = 170</span></div>\n<div class=\"rrow\"><span class=\"rl\">Por descomposición</span><span class=\"ra\">61 + 23 = (60+20)+(1+3)</span></div>\n<div class=\"rrow\"><span class=\"rl\">Con la cuenta parada</span><span class=\"ra\">una cifra debajo de la otra</span></div>\n<p class=\"exline\">Las tres valen. Elegí la que te salga más rápido y después <b>revisá</b>.</p></div>\n<div class=\"rsec\"><h4>Descomponer para sumar</h4>\n<p class=\"exline\">Se suman por separado las decenas y las unidades, y después se juntan los dos resultados. En las restas funciona igual.</p></div>\n<div class=\"rsec\"><h4>Cómo controlar una resta</h4>\n<div class=\"warn\">Si la resta dio bien, al <b>sumar</b> el resultado con el número que restaste tiene que volver a dar el primero.<br>\n500 − 240 = 260 &nbsp;&rarr;&nbsp; 260 + 240 = 500 &#10003;<br><br>\nEs la forma más rápida de darte cuenta sola de si te equivocaste, sin preguntar.</div></div>","ex":[{"t":"fill","q":"Calculá mentalmente","labels":["230 + 40","125 + 30","300 − 70","86 − 20","145 + 55","420 − 120"],"a":["270","155","230","66","200","300"]},{"t":"fill","q":"Resolvé las cuentas","h":"Podés hacerlas en papel y escribir acá el resultado","labels":["247 + 136","358 + 275","562 − 238","704 − 356"],"a":["383","633","324","348"]},{"t":"fill","q":"Resolvé por descomposición","h":"Ejemplo: 34 + 25 = (30 + 20) + (4 + 5) = 50 + 9 = 59","labels":["42 + 36","76 − 24"],"a":["78","52"]},{"t":"open","q":"Inventá una suma cuyo resultado sea 100","model":"Hay muchísimas respuestas correctas: 60 + 40, 75 + 25, 99 + 1, 50 + 50. Lo importante es que al sumar dé exactamente 100."}]},{"id":"m4","dot":"🧩","name":"Día 4","title":"Día 4 · Problemas","sub":"Entender qué pasa antes de elegir la cuenta","rules":"\n<div class=\"rsec\"><h4>Primero pensá qué está pasando</h4>\n<p class=\"exline\">No busques la cuenta de entrada. Preguntate qué ocurre en la historia:</p>\n<div class=\"rrow\"><span class=\"rl\">se agrega, se junta, se avanza</span><span class=\"ra\">SUMA</span></div>\n<div class=\"rrow\"><span class=\"rl\">se quita, se separa, se retrocede</span><span class=\"ra\">RESTA</span></div>\n<div class=\"rrow\"><span class=\"rl\">se comparan dos cantidades</span><span class=\"ra\">RESTA</span></div></div>\n<div class=\"rsec\"><h4>&#9888; La trampa de la palabra \"más\"</h4>\n<div class=\"warn\">\"¿Cuántos puntos <b>más</b> tiene Ana que Luis?\" tiene la palabra <b>más</b>, pero se resuelve <b>restando</b>, porque se están comparando dos cantidades.<br><br>\nLa palabra suelta no decide nada. Decide <b>lo que pasa en la historia</b>.</div></div>\n<div class=\"rsec\"><h4>Revisá que la respuesta tenga sentido</h4>\n<p class=\"exline\">Si alguien <b>regala</b> algo, tiene que quedarle <b>menos</b> que antes. Si <b>recibe</b>, más. Si el resultado va para el lado contrario, la cuenta está mal elegida.</p></div>","ex":[{"t":"fill","e":"📚","q":"En la biblioteca había <b>238</b> libros y llegaron <b>125</b> nuevos. ¿Cuántos libros hay ahora?","labels":["Respuesta"],"a":["363"],"why":"Llegan más libros, así que se juntan: 238 + 125 = 363."},{"t":"fill","e":"🃏","q":"Martina tenía <b>350</b> figuritas y regaló <b>127</b>. ¿Cuántas le quedaron?","labels":["Respuesta"],"a":["223"],"why":"Regalar es quitar: 350 − 127 = 223."},{"t":"fill","e":"🚌","q":"Un colectivo está en la parada <b>145</b> y avanza <b>28</b> paradas. ¿A qué parada llega?","labels":["Respuesta"],"a":["173"],"why":"Avanzar es sumar: 145 + 28 = 173."},{"t":"choice","q":"Tomás tiene <b>186</b> cartas y Julia tiene <b>149</b>. ¿Cuántas cartas MÁS tiene Tomás?","h":"¿Qué cuenta hay que hacer?","o":["Sumar","Restar"],"a":1,"why":"Aunque diga «más», se comparan dos cantidades. Eso se resuelve restando."},{"t":"fill","q":"Entonces, ¿cuántas cartas más tiene Tomás?","labels":["Respuesta"],"a":["37"],"why":"186 − 149 = 37 cartas."},{"t":"fill","e":"🎮","q":"Sofi tenía <b>420</b> puntos y retrocedió <b>65</b>. ¿Con cuántos puntos queda?","labels":["Respuesta"],"a":["355"],"why":"Retroceder es restar: 420 − 65 = 355."}]},{"id":"m5","dot":"✖️","name":"Día 5","title":"Día 5 · Suma repetida y reparto","sub":"La puerta de entrada a la multiplicación y la división","rules":"\n<div class=\"rsec\"><h4>Suma repetida</h4>\n<p class=\"exline\">Cuando la <b>misma cantidad se repite</b>, se puede sumar varias veces en lugar de contar de a uno.</p>\n<div class=\"rrow\"><span class=\"rl\">2 cajas con 5 lápices</span><span class=\"ra\">5 + 5 = 10</span></div>\n<div class=\"warn\"><b>&#9888; El orden importa.</b> En \"2 cajas con 5 lápices\" lo que se repite es el <b>5</b>, dos veces. No es 2 + 2 + 2 + 2 + 2.<br><br>\nEl primer número dice <b>cuántos grupos hay</b>; el segundo, <b>cuánto hay en cada grupo</b>. Se repite el segundo, tantas veces como diga el primero.</div></div>\n<div class=\"rsec\"><h4>Repartir en partes iguales</h4>\n<p class=\"exline\">Es lo contrario: todos reciben <b>la misma cantidad</b>, sin que a nadie le toque de más.</p>\n<div class=\"rrow\"><span class=\"rl\">10 figuritas entre 2 chicos</span><span class=\"ra\">5 cada uno</span></div></div>\n<div class=\"rsec\"><h4>Cuando sobra</h4>\n<p class=\"exline\">No siempre entra justo. Con <b>9 caramelos entre 2 chicos</b>, cada uno recibe 4 y <b>sobra 1</b>: ese resto no se puede repartir sin partirlo.</p>\n<div class=\"warn\">Si sobra, la respuesta tiene <b>dos partes</b>: cuánto recibe cada uno <b>y</b> cuánto sobró. Contestar solo una de las dos deja el ejercicio incompleto.</div></div>","ex":[{"t":"fill","q":"3 platos con 4 galletitas en cada uno","viz":{"k":"groups","g":3,"per":4},"labels":["Suma repetida","Total"],"a":["4+4+4","12"],"why":"Se repite el 4, tres veces."},{"t":"fill","q":"5 bolsas con 2 naranjas en cada una","viz":{"k":"groups","g":5,"per":2},"labels":["Suma repetida","Total"],"a":["2+2+2+2+2","10"],"why":"Se repite el 2, cinco veces."},{"t":"fill","q":"Escribí la suma repetida y el total: <b>4 veces 5</b>","labels":["Suma","Total"],"a":["5+5+5+5","20"]},{"t":"fill","q":"Escribí la suma repetida y el total: <b>3 veces 6</b>","labels":["Suma","Total"],"a":["6+6+6","18"]},{"t":"fill","q":"Repartí en partes iguales. ¿Cuántos recibe cada uno?","labels":["12 lápices entre 3 chicos","20 galletitas entre 5 chicos"],"a":["4","4"]},{"t":"fill","q":"14 caramelos entre 4 chicos","viz":{"k":"groups","g":4,"per":3,"left":2},"labels":["Recibe cada uno","Sobran"],"a":["3","2"],"why":"3 para cada uno son 12, y quedan 2 sueltos."},{"t":"open","q":"Explicá con tus palabras: ¿qué significa repartir en partes iguales?","model":"Lo que se espera: que diga que TODOS reciben la misma cantidad, que a nadie le toca más ni menos. Si lo explica con un ejemplo propio, mejor todavía."}]},{"id":"m6","dot":"🤔","name":"Día 6","title":"Día 6 · ¿Qué cuenta va?","sub":"Suma o suma repetida · separar · comparar","ex":[{"t":"choice","e":"💐","q":"En un florero hay <b>7 rosas</b> y <b>5 margaritas</b>. ¿Cuántas flores hay?","h":"¿Qué cuenta resuelve el problema?","o":["7 + 5","7 + 7 + 7 + 7 + 7","5 + 5 + 5 + 5 + 5 + 5 + 5"],"a":0},{"t":"choice","q":"Hay <b>4 floreros</b> con <b>5 flores</b> en cada uno. ¿Cuántas flores hay?","viz":{"k":"groups","g":4,"per":5},"h":"¿Qué cuenta resuelve el problema?","o":["4 + 5","5 + 5 + 5 + 5","4 + 4 + 4"],"a":1},{"t":"choice","q":"¿Cuál de estos problemas se resuelve con una <b>suma repetida</b>?","o":["Tengo 8 bolitas y me regalan 6","En cada mano tengo 5 dedos. ¿Cuántos dedos tengo en las dos manos?","Tengo 12 caramelos y como 3"],"a":1},{"t":"fill","q":"Hay <b>3 mesas</b> con <b>6 sillas</b> cada una. ¿Cuántas sillas hay?","viz":{"k":"groups","g":3,"per":6},"labels":["Respuesta"],"a":["18"],"why":"Se repite el 6 tres veces: 6 + 6 + 6 = 18."},{"t":"fill","q":"Sofía tiene <b>9 figuritas</b> y Tomás tiene <b>6</b>. ¿Cuántas tienen entre los dos?","labels":["Respuesta"],"a":["15"],"why":"Son dos cantidades distintas que se juntan: 9 + 6 = 15."},{"t":"choice","q":"En un grado hay <b>28 chicos</b>. <b>13</b> son varones. ¿Cuántas son nenas?","h":"¿Qué cuenta hay que hacer?","o":["Sumar","Restar"],"a":1,"why":"Las nenas son la otra parte del total: se separa."},{"t":"fill","q":"Entonces, ¿cuántas nenas hay en ese grado?","labels":["Respuesta"],"a":["15"]},{"t":"fill","q":"En la granja hay <b>54 animales</b>. <b>30</b> son gallinas y el resto son patos. ¿Cuántos patos hay?","labels":["Respuesta"],"a":["24"],"why":"54 − 30 = 24 patos."},{"t":"fill","q":"Lucas mide <b>125 cm</b> y su hermana mide <b>98 cm</b>. ¿Cuántos centímetros más mide Lucas?","labels":["Respuesta"],"a":["27"],"why":"Se comparan dos medidas: 125 − 98 = 27."},{"t":"fill","e":"🚃","q":"Un tren tiene <b>5 vagones</b> y en cada vagón viajan <b>10 personas</b>. ¿Cuántas personas viajan?","labels":["Respuesta"],"a":["50"]}],"rules":"\n<div class=\"rsec\"><h4>¿Suma o suma repetida?</h4>\n<div class=\"rrow\"><span class=\"rl\">Cantidades <b>distintas</b> que se juntan</span><span class=\"ra\">suma común</span></div>\n<div class=\"rrow\"><span class=\"rl\">La <b>misma cantidad</b> muchas veces</span><span class=\"ra\">suma repetida</span></div>\n<p class=\"exline\">\"Tengo 3 perros y 2 gatos\" &rarr; 3 + 2.<br>\"Tengo 3 perros y cada uno tiene 4 patas\" &rarr; 4 + 4 + 4.</p>\n<div class=\"warn\"><b>La pista:</b> si aparece \"<b>cada uno</b>\", \"<b>en cada</b>\" o \"<b>de a</b>\", casi siempre hay grupos iguales. Igual leé bien: la palabra sola no decide.</div></div>\n<div class=\"rsec\"><h4>Separar una parte del total</h4>\n<p class=\"exline\">Cuando conocés el <b>total</b> y <b>una parte</b>, la otra parte se encuentra <b>restando</b>.</p>\n<div class=\"rrow\"><span class=\"rl\">En una bolsa hay 20 frutas; 8 son peras</span><span class=\"ra\">20 − 8 = manzanas</span></div></div>\n<div class=\"rsec\"><h4>Comparar</h4>\n<p class=\"exline\">\"¿Cuánto más…?\" o \"¿Cuánto menos…?\" compara dos cantidades. Se resuelve <b>restando</b> la chica de la grande.</p></div>"},{"id":"mc","dot":"✏️","name":"Cuentas paradas","title":"Cuentas paradas","sub":"Sumar, restar y multiplicar de tres cifras","rules":"\n<div class=\"rsec\"><h4>Cómo se arma una cuenta parada</h4>\n<div class=\"rrow\"><span class=\"rl num\">1</span><span class=\"rl\">Las unidades debajo de las unidades, las decenas debajo de las decenas.</span></div>\n<div class=\"rrow\"><span class=\"rl num\">2</span><span class=\"rl\">Se empieza por la <b>derecha</b>, por la columna de las unidades.</span></div>\n<div class=\"rrow\"><span class=\"rl num\">3</span><span class=\"rl\">Si el resultado de una columna pasa de 9, se escribe la última cifra y <b>te llevás</b> la otra a la columna de al lado.</span></div>\n<div class=\"warn\">En esta página, los casilleros chiquitos de arriba son para anotar lo que te llevás, igual que en el cuaderno. <b>No se corrigen</b>: son tuyos para pensar.</div></div>\n<div class=\"rsec\"><h4>Cuando no alcanza para restar</h4>\n<p class=\"exline\">Si el número de arriba es más chico que el de abajo en esa columna, se le <b>pide prestado</b> a la columna de la izquierda. Esa columna pierde 1.</p>\n<div class=\"warn\"><b>Para controlar:</b> sumá el resultado con el número que restaste. Tiene que volver a darte el número de arriba.</div></div>\n<div class=\"rsec\"><h4>Multiplicar en cuenta parada</h4>\n<p class=\"exline\">Se multiplica cada cifra de arriba por la de abajo, <b>empezando por la derecha</b>. Si pasa de 9, se escribe la última cifra y te llevás la otra.</p>\n<div class=\"warn\">Lo que te llevás en una multiplicación <b>se suma</b> después de multiplicar, no antes.</div></div>","ex":[{"t":"col","op":"+","n":[247,136],"w":3,"res":"383","rows":["247","136"],"q":"247 + 136"},{"t":"col","op":"+","n":[358,275],"w":3,"res":"633","rows":["358","275"],"q":"358 + 275"},{"t":"col","op":"+","n":[125,48,230],"h":"Tres sumandos","w":3,"res":"403","rows":["125"," 48","230"],"q":"125 + 48 + 230"},{"t":"col","op":"−","n":[562,238],"w":3,"res":"324","rows":["562","238"],"q":"562 − 238"},{"t":"col","op":"−","n":[704,356],"h":"Ojo con el cero del medio","w":3,"res":"348","rows":["704","356"],"q":"704 − 356"},{"t":"col","op":"−","n":[500,164],"w":3,"res":"336","rows":["500","164"],"q":"500 − 164"},{"t":"col","op":"+","n":[1204,397],"w":4,"res":"1601","rows":["1204"," 397"],"q":"1204 + 397"},{"t":"col","op":"−","n":[1000,625],"w":4,"res":" 375","rows":["1000"," 625"],"q":"1000 − 625"},{"t":"col","op":"×","n":[123,2],"h":"Multiplicá cada cifra, empezando por la derecha","w":3,"res":"246","rows":["123","  2"],"q":"123 × 2"},{"t":"col","op":"×","n":[214,3],"w":3,"res":"642","rows":["214","  3"],"q":"214 × 3"},{"t":"col","op":"×","n":[136,4],"h":"Acá hay que llevarse varias veces","w":3,"res":"544","rows":["136","  4"],"q":"136 × 4"}]},{"id":"mcd","dot":"🏠","name":"La casita","title":"La casita","sub":"Repartir, escrito como en el cuaderno","rules":"\n<div class=\"rsec\"><h4>Una forma nueva de anotar el reparto</h4>\n<p class=\"exline\">Hasta ahora repartías contando o dibujando. Esta es la manera de <b>escribirlo</b>, y se usa toda la primaria.</p>\n<div class=\"rrow\"><span class=\"rl\">el número que se reparte</span><span class=\"ra\">va adentro</span></div>\n<div class=\"rrow\"><span class=\"rl\">entre cuántos se reparte</span><span class=\"ra\">va afuera, a la derecha</span></div>\n<div class=\"rrow\"><span class=\"rl\">cuánto le toca a cada uno</span><span class=\"ra\">debajo del divisor</span></div>\n<div class=\"rrow\"><span class=\"rl\">lo que sobra</span><span class=\"ra\">el resto</span></div>\n<div class=\"warn\"><b>Un truco que ya sabés:</b> para repartir 46 entre 2, preguntate <b>qué número por 2 da 46</b>. Si no te sale de memoria, probá: 20 × 2 = 40, te faltan 6, y 3 × 2 = 6. Entonces son 23.<br>\n<b>Para controlar:</b> multiplicá lo que le tocó a cada uno por la cantidad de chicos y sumale el resto. Tiene que darte el número de adentro.</div></div>","ex":[{"t":"div","D":96,"d":3,"w":2,"co":"32","r":"0","q":"96 ÷ 3"},{"t":"div","D":148,"d":4,"w":3,"co":"37","r":"0","q":"148 ÷ 4"},{"t":"div","D":175,"d":5,"w":3,"co":"35","r":"0","q":"175 ÷ 5"},{"t":"div","D":243,"d":9,"w":3,"co":"27","r":"0","q":"243 ÷ 9"},{"t":"div","D":137,"d":6,"h":"Acá va a sobrar algo","w":3,"co":"22","r":"5","q":"137 ÷ 6"},{"t":"div","D":250,"d":8,"w":3,"co":"31","r":"2","q":"250 ÷ 8"}]},{"id":"msim","dot":"📝","name":"Simulacro","title":"Simulacro de examen","sub":"Sin mirar los ejemplos · 35 a 40 minutos","rules":"\n<div class=\"rsec\"><h4>Antes de empezar</h4>\n<p class=\"exline\">Leé <b>todo</b> el examen antes de escribir la primera respuesta. Resolvé primero lo que te sale seguro y dejá para el final lo que te cuesta.</p></div>\n<div class=\"rsec\"><h4>Al terminar, revisá tres cosas</h4>\n<div class=\"rrow\"><span class=\"rl num\">1</span><span class=\"rl\">¿Contestaste todas las consignas?</span></div>\n<div class=\"rrow\"><span class=\"rl num\">2</span><span class=\"rl\">¿Copiaste bien los números del enunciado?</span></div>\n<div class=\"rrow\"><span class=\"rl num\">3</span><span class=\"rl\">¿La respuesta tiene sentido?</span></div>\n<div class=\"warn\">Este módulo entra en el repaso completo: aparecen juntos los cinco días anteriores. Si algo no sale, el tema está en el día que lo trabajó.</div></div>","ex":[{"t":"order","q":"1. Ordená de menor a mayor","items":["705","570","75","750","507"],"a":["75","507","570","705","750"]},{"t":"fill","q":"2. Descomponé","labels":["684 =","1.307 ="],"a":["600+80+4","1000+300+7"]},{"t":"fill","q":"3. Completá","labels":["100 más que 456","100 menos que 823","1.000 más que 2.145","Uno menos que 1.000"],"a":["556","723","3145","999"]},{"t":"fill","q":"4. Resolvé","labels":["268 + 157","603 − 278"],"a":["425","325"]},{"t":"fill","q":"5. En una escuela juntaron <b>175</b> tapitas el lunes y <b>148</b> el martes. ¿Cuántas juntaron en total?","labels":["Respuesta"],"a":["323"],"why":"175 + 148 = 323 tapitas."},{"t":"fill","q":"6. En una caja había <b>320</b> lápices. Se repartieron <b>85</b>. ¿Cuántos quedaron?","labels":["Respuesta"],"a":["235"],"why":"320 − 85 = 235 lápices."},{"t":"fill","q":"7. Hay <b>4 paquetes</b> con <b>5 figuritas</b> cada uno. ¿Cuántas figuritas hay?","labels":["Suma repetida","Total"],"a":["5+5+5+5","20"]},{"t":"fill","q":"8. Se reparten <b>18 marcadores</b> entre <b>3 equipos</b> en partes iguales. ¿Cuántos recibe cada equipo?","labels":["Respuesta"],"a":["6"]},{"t":"fill","q":"9. Completá la serie: 250 – 300 – 350 – ...","labels":["",""],"a":["400","450"]},{"t":"fill","q":"10. Escribí un número entre 1.498 y 1.500","labels":[""],"a":["1499"]}]}]},{"id":"lengua","name":"Lengua","emo":"📖","tag":"","desc":"Lectura, escritura, poesía y ortografía","c1":"#3E9E5F","c2":"#86C252","units":[{"id":"l1","dot":"📕","name":"Día 1","title":"Día 1 · Antes, durante y después de leer","sub":"Anticipar, preguntarse y recapitular","rules":"\n<div class=\"rsec\"><h4>Cómo se trabaja un libro álbum</h4>\n<p class=\"exline\">En un libro álbum <b>las ilustraciones también cuentan la historia</b>. A veces muestran algo distinto de lo que dicen las palabras, y ahí suele estar la gracia.</p>\n<div class=\"rrow\"><span class=\"rl\">Antes de leer</span><span class=\"ra\">mirar la tapa y anticipar</span></div>\n<div class=\"rrow\"><span class=\"rl\">Durante</span><span class=\"ra\">anotar dudas y detalles</span></div>\n<div class=\"rrow\"><span class=\"rl\">Después</span><span class=\"ra\">contar con tus palabras</span></div></div>\n<div class=\"rsec\"><h4>Anticipar no es adivinar</h4>\n<p class=\"exline\">Cuando mirás la tapa y decís de qué va a tratar, tenés que poder explicar <b>en qué te basaste</b>: algo que se ve en el dibujo o que dice el título.</p>\n<div class=\"warn\"><b>Para el adulto:</b> esta unidad casi no se corrige sola, porque las respuestas dependen del ejemplar que tiene delante. Lo que se evalúa no es acertar, sino que <b>sostenga lo que dice con algo del libro</b>. Tené el libro al lado.</div></div>","ex":[{"t":"open","q":"Mirá la tapa. ¿Qué personajes aparecen? ¿De qué pensás que va a tratar el cuento? ¿Qué te hace pensar eso?","model":"No hay una respuesta correcta: es una hipótesis. Lo que importa es que la justifique con algo que VE en la tapa («porque el perro está arriba de la cama», «porque el nene tiene cara de…»)."},{"t":"fill","q":"¿Cómo se llama el perro?","labels":[""],"a":["clovis"]},{"t":"open","q":"Anotá una pregunta que te haya surgido mientras leías","model":"Cualquier pregunta genuina sirve. Si no se le ocurre ninguna, relean juntos una página y preguntale qué le llamó la atención."},{"t":"open","q":"Elegí una ilustración que te haya llamado la atención y contá por qué","model":"Se busca que describa lo que ve y que diga qué le produjo. Pedile que señale la página."},{"t":"open","q":"¿Qué quiere averiguar el niño?","model":"La idea central: el nene quiere saber cómo hace su mamá para estar tan segura de que él no es un perro."},{"t":"open","q":"¿Qué relación hay entre el niño y Clovis?","model":"Son amigos, compañeros, hacen todo juntos. Si dice «son amigos» a secas, pedile un ejemplo del libro."}],"books":[{"id":"vida-de-perros","title":"Vida de perros"}]},{"id":"l2","dot":"🔎","name":"Día 2","title":"Día 2 · Comprensión lectora","sub":"Volver al texto a buscar las pistas","rules":"\n<div class=\"rsec\"><h4>La regla de oro de la comprensión</h4>\n<div class=\"warn\">Si no se acuerda de algo, <b>no se adivina: se vuelve al libro a buscarlo</b>. Esa es la destreza que se evalúa, más que la memoria.</div></div>\n<div class=\"rsec\"><h4>Responder con oraciones completas</h4>\n<div class=\"rrow\"><span class=\"rl\"><span class=\"no\">&#10007;</span> \"en la casa\"</span><span class=\"ra\">incompleta</span></div>\n<div class=\"rrow\"><span class=\"rl\"><span class=\"yes\">&#10003;</span> \"Los dos juegan en la casa.\"</span><span class=\"ra\">completa</span></div>\n<p class=\"exline\">Una respuesta completa se entiende sola, sin leer la pregunta.</p></div>\n<div class=\"rsec\"><h4>Texto e ilustración</h4>\n<p class=\"exline\">Antes de responder sobre un dibujo, mirálo de nuevo y preguntate: ¿esto que veo <b>está dicho</b> en las palabras, o lo <b>agrega</b> la imagen?</p></div>","ex":[{"t":"open","q":"¿Qué le pregunta el niño a su mamá?","model":"Debe reconstruir la pregunta del nene sobre cómo ella sabe que él no es un perro."},{"t":"open","q":"¿Qué razones le da la mamá para explicarle que no es un perro?","model":"Que busque las razones en el libro y las diga con sus palabras. Si da una sola, pedile otra."},{"t":"open","q":"¿Qué hacen el niño y Clovis cuando están juntos? Escribí dos acciones que aparezcan en el cuento","model":"Dos acciones concretas, sacadas del libro. Pedile que te muestre dónde las vio."},{"t":"open","q":"¿Las ilustraciones muestran lo mismo que dicen las palabras, o agregan información? Contá un ejemplo","model":"La respuesta esperada: AGREGAN. A veces hasta contradicen el texto, y ahí aparece el humor. Lo importante es el ejemplo concreto."},{"t":"open","q":"¿Qué parte te resultó más graciosa? ¿Por qué?","model":"Pregunta de opinión: cualquier respuesta vale si explica el porqué."},{"t":"open","q":"¿Cómo describirías la amistad entre el niño y Clovis?","model":"Se espera algo más que «buena»: que use dos o tres características."},{"t":"open","q":"¿Qué título alternativo le pondrías al cuento? ¿Por qué?","model":"El título puede ser cualquiera, pero la justificación tiene que conectarse con algo del cuento."},{"t":"open","q":"Ordená los momentos principales del cuento (1, 2 y 3) revisando el libro:<br>— El niño comparte juegos y aventuras con Clovis.<br>— El niño le hace una pregunta a su mamá.<br>— La historia muestra cómo se comportan los dos amigos.","model":"El orden se decide revisando el libro, no de memoria. Que te lo justifique señalando las páginas."}],"books":[{"id":"vida-de-perros","title":"Vida de perros"}]},{"id":"l3","dot":"🗣️","name":"Día 3","title":"Día 3 · Personajes, lugares y vocabulario","sub":"Describir y buscar palabras nuevas","rules":"\n<div class=\"rsec\"><h4>Describir no es nombrar</h4>\n<div class=\"rrow\"><span class=\"rl\"><span class=\"no\">&#10007;</span> \"Es un gato\"</span><span class=\"ra\">lo nombra</span></div>\n<div class=\"rrow\"><span class=\"rl\"><span class=\"yes\">&#10003;</span> \"Es un gato curioso que se mete en todos lados\"</span><span class=\"ra\">lo describe</span></div>\n<p class=\"exline\">Una buena descripción dice <b>cómo es</b>, <b>qué hace</b> y <b>cómo se relaciona</b> con los demás. Con una sola de las tres no alcanza.</p></div>\n<div class=\"rsec\"><h4>Palabras nuevas</h4>\n<p class=\"exline\">Cuando aparece una palabra que no conocés, primero tratá de <b>adivinar qué significa por el contexto</b>: leé la oración entera y las de alrededor. Recién después se pregunta o se busca.</p>\n<div class=\"warn\">Esa estrategia es la que se evalúa. Preguntar de entrada es más rápido, pero no entrena nada.</div></div>","ex":[{"t":"open","q":"Describí al niño: cómo es, qué hace, cómo se relaciona con los demás","model":"Pedí al menos dos características y un ejemplo del libro."},{"t":"open","q":"Describí a Clovis con el mismo criterio","model":"Igual que antes: cómo es, qué hace, cómo se lleva con el nene."},{"t":"open","q":"Elegí dos lugares o espacios que aparezcan en las ilustraciones y describilos","model":"Tiene que mirar las ilustraciones, no inventar. Que señale las páginas."},{"t":"open","q":"Buscá en el libro tres palabras que te parezcan importantes o nuevas, y escribí qué significan","model":"Si las tres son fáciles, pedile una que de verdad no conociera. Primero que adivine por contexto, después se confirma."},{"t":"open","q":"Escribí tres palabras que describan la amistad entre el niño y Clovis","model":"Por ejemplo: compañerismo, lealtad, diversión, confianza. Cualquier terna razonable sirve."},{"t":"open","q":"¿Por qué creés que el libro se llama «Vida de perros»?","model":"Pregunta de interpretación. Lo que se evalúa es que conecte el título con algo del cuento, no que acierte una lectura única."}],"books":[{"id":"vida-de-perros","title":"Vida de perros"}]},{"id":"l4","dot":"✏️","name":"Día 4","title":"Día 4 · Escritura","sub":"Recomendar, narrar e instruir","rules":"\n<div class=\"rsec\"><h4>Un relato se arma en tres partes</h4>\n<div class=\"rrow\"><span class=\"rl\">Comienzo</span><span class=\"ra\">quién y dónde</span></div>\n<div class=\"rrow\"><span class=\"rl\">Nudo</span><span class=\"ra\">qué sucede, el problema</span></div>\n<div class=\"rrow\"><span class=\"rl\">Final</span><span class=\"ra\">cómo se resuelve</span></div>\n<div class=\"warn\"><b>&#9888; Si falta el nudo, no hay cuento:</b> hay una descripción. El nudo es algo que <b>pasa</b> y que cambia la situación.</div></div>\n<div class=\"rsec\"><h4>Conectores de orden</h4>\n<p class=\"exline\">Un texto de instrucciones encadena los pasos con conectores que indican <b>en qué momento</b> va cada uno: hay uno para arrancar, otros para el medio y uno para cerrar.</p></div>\n<div class=\"rsec\"><h4>Revisar antes de entregar</h4>\n<p class=\"exline\">Tres cosas, siempre: <b>mayúscula</b> al empezar, <b>punto</b> al terminar y <b>espacios</b> entre las palabras. Esa revisión propia también se evalúa.</p></div>","ex":[{"t":"order","q":"Ordená los conectores para escribir instrucciones","h":"Tocalos en el orden en que se usan","items":["Luego","Finalmente","Primero","Después"],"a":["Primero","Después","Luego","Finalmente"]},{"t":"open","q":"Escribí una recomendación del cuento para un compañero: de qué trata (sin contar el final) y por qué lo recomendarías","model":"Dos cosas tienen que estar: de qué trata Y por qué lo recomienda. Si contó el final, pedile que lo reescriba sin spoilear."},{"t":"open","q":"Inventá una nueva aventura para el niño y Clovis. Poné título, comienzo, qué sucede y final","paper":true,"model":"Conviene hacerla en el cuaderno, con renglones. Revisá que tenga las tres partes: si solo describe, falta el «qué sucede»."},{"t":"open","q":"Escribí instrucciones para cuidar a un perro, usando primero, después, luego y finalmente","model":"Cuatro pasos, uno por conector, y que cada paso sea una acción concreta («darle de comer», no «cuidarlo bien»)."}]},{"id":"l5","dot":"🔤","name":"Día 5","title":"Día 5 · Ortografía","sub":"MB · MP · R · RR · B · V · puntuación","rules":"\n<div class=\"rsec\"><h4>1. Antes de B y P va M, nunca N</h4>\n<div class=\"rrow\"><span class=\"rl\">ho<b>mb</b>re, ca<b>mb</b>io</span><span class=\"ra\">MB</span></div>\n<div class=\"rrow\"><span class=\"rl\">si<b>mp</b>le, i<b>mp</b>ortante</span><span class=\"ra\">MP</span></div>\n<div class=\"warn\">Es una regla <b>sin excepciones</b> en castellano. Si al decirla suena \"n\" y después viene <b>b</b> o <b>p</b>, se escribe <b>m</b>.</div></div>\n<div class=\"rsec\"><h4>2. R o RR</h4>\n<div class=\"rrow\"><span class=\"rl\">suena FUERTE entre vocales</span><span class=\"ra\">RR</span></div>\n<div class=\"rrow\"><span class=\"rl\">suena fuerte al PRINCIPIO</span><span class=\"ra\">una sola R</span></div>\n<div class=\"rrow\"><span class=\"rl\">suena SUAVE entre vocales</span><span class=\"ra\">una sola R</span></div>\n<p class=\"exline\">to<b>rr</b>e, ja<b>rr</b>a &rarr; doble, porque vibra entre vocales.<br>\n<b>r</b>ueda &rarr; una sola, aunque suene fuerte, porque está al principio.<br>\nca<b>r</b>a, pe<b>r</b>a &rarr; una sola, porque suena suave.</p>\n<div class=\"warn\"><b>Prueba del sonido:</b> decí la palabra en voz alta y alargá la erre. Si vibra (to-rrrr-e), van dos. Si no vibra, va una.</div></div>\n<div class=\"rsec\"><h4>3. B o V</h4>\n<p class=\"exline\">Acá no hay una regla que sirva siempre: estas palabras <b>se aprenden de memoria</b>. Ejemplos: <b>b</b>arco, <b>v</b>aca.</p>\n<div class=\"warn\">Si dudás, pensá si conocés otra palabra de la misma familia que ya sepas escribir.</div></div>\n<div class=\"rsec\"><h4>4. Puntuación</h4>\n<p class=\"exline\">Cada oración empieza con <b>mayúscula</b> y termina con <b>punto</b>. Los nombres propios llevan mayúscula estén donde estén.</p></div>","ex":[{"t":"fill","q":"Separá las palabras y escribí la oración correctamente","h":"ELNIÑOJUEGACONCLOVIS.","labels":[""],"a":["el nino juega con clovis"],"why":"El niño juega con Clovis."},{"t":"fill","q":"Separá las palabras y escribí la oración correctamente","h":"ELPERROESUNGRANAMIGO.","labels":[""],"a":["el perro es un gran amigo"],"why":"El perro es un gran amigo."},{"t":"fill","q":"Completá con MB o MP y escribí la palabra entera","labels":["ta__or","ca__ana","so__ra","tie__o"],"a":["tambor","campana","sombra","tiempo"]},{"t":"fill","q":"Completá con MB o MP y escribí la palabra entera","labels":["bo__ón","ca__o"],"a":["bombon","campo"]},{"t":"fill","q":"Completá con R o RR y escribí la palabra entera","labels":["pe__o (el animal)","ca__o (el vehículo)","co__er","pe__era"],"a":["perro","carro","correr","perrera"]},{"t":"choice","q":"El niño es un ___ amigo.","o":["buen","vuén"],"a":0},{"t":"choice","q":"Clovis corre por el ___.","o":["varrio","barrio"],"a":1},{"t":"choice","q":"El niño ___ con su perro.","o":["jueja","juega"],"a":1},{"t":"open","q":"Revisá este texto: agregá mayúsculas, puntos y espacios donde hagan falta<br><b>unniñoteníaunperrollamadoclovisjuntosjugabanmuchotodoslosdías</b>","model":"Un niño tenía un perro llamado Clovis. Juntos jugaban mucho todos los días.\n\nSon DOS oraciones: cada una con mayúscula al empezar y punto al terminar. Clovis va con mayúscula por ser nombre propio."},{"t":"open","q":"Escribí una oración que tenga una palabra con MB y otra con RR","model":"Por ejemplo: «La sombra del perro corría por el barrio». Revisá que las dos palabras estén y que la oración tenga mayúscula y punto."}]},{"id":"lsim","dot":"📝","name":"Día 6 · Simulacro","title":"Día 6 · Otros textos y simulacro","sub":"Texto instructivo + examen de práctica","rules":"\n<div class=\"rsec\"><h4>Tres tipos de texto</h4>\n<div class=\"rrow\"><span class=\"rl\">Cuento</span><span class=\"ra\">narra una historia inventada</span></div>\n<div class=\"rrow\"><span class=\"rl\">Instrucciones</span><span class=\"ra\">explican cómo hacer algo</span></div>\n<div class=\"rrow\"><span class=\"rl\">Noticia</span><span class=\"ra\">informa un hecho real</span></div>\n<p class=\"exline\">Para decidir cuál es, preguntate <b>para qué fue escrito</b>: ¿para entretener, para enseñar a hacer algo, o para contar algo que pasó?</p></div>\n<div class=\"rsec\"><h4>Texto para leer (Parte A)</h4>\n<div class=\"rrow\"><span class=\"rl\" style=\"text-align:left\"><b>Cómo preparar un lugar cómodo para leer</b><br>\n1. Buscá un lugar tranquilo.<br>\n2. Elegí un libro que te guste.<br>\n3. Sentate cómodamente y tené buena luz.<br>\n4. Leé con atención y, si una palabra no se entiende, volvé a leer la oración.</span></div></div>","ex":[{"t":"choice","q":"Parte A · ¿Qué tipo de texto es el de arriba?","o":["Cuento","Instrucciones","Noticia"],"a":1,"why":"Va en pasos numerados y los verbos dan órdenes."},{"t":"open","q":"Parte A · ¿Para qué sirve ese texto?","model":"Para explicar cómo preparar un lugar cómodo antes de ponerse a leer."},{"t":"choice","q":"Parte A · ¿Qué tenés que hacer si no entendés una palabra?","o":["Saltearla y seguir","Volver a leer la oración","Cerrar el libro"],"a":1},{"t":"fill","q":"Parte B · 1. Título y autora del libro que leíste","labels":["Título","Autora"],"a":["vida de perros","isol"]},{"t":"open","q":"Parte B · 2. Nombrá dos personajes y describí a uno de ellos","model":"Los dos personajes centrales son el niño y Clovis. La descripción tiene que decir cómo es o qué hace, no solo nombrarlo."},{"t":"open","q":"Parte B · 3. Contá con tus palabras de qué trata el cuento, en 3 o 4 oraciones","paper":true,"model":"Que entren: quiénes son, qué pasa y cómo termina. Conviene hacerlo en el cuaderno y después leerlo en voz alta para ver si se entiende."},{"t":"open","q":"Parte B · 4. Escribí una recomendación de dos oraciones para otro chico","model":"Dos oraciones, no una: una dice de qué trata, la otra por qué lo recomienda."},{"t":"open","q":"Parte B · 5. Corregí esta oración:<br><b>el niño juega con clovis y son muy amigos</b>","model":"El niño juega con Clovis y son muy amigos.\n\nTres cambios: mayúscula inicial, Clovis con mayúscula (nombre propio) y punto final."},{"t":"fill","q":"Parte B · 6. Completá y escribí la palabra entera","labels":["ta__or (MB/MP)","pe__o (R/RR, el animal)","ba__io (R/RR)"],"a":["tambor","perro","barrio"]}],"books":[{"id":"vida-de-perros","title":"Vida de perros"}]},{"id":"l7","dot":"👹","name":"Más cuentos","title":"Otros cuentos del programa","sub":"«Secreto de familia» · «Petit, el monstruo»","ex":[{"t":"fill","q":"¿Quién escribió «Petit, el monstruo»?","labels":[""],"a":["isol"]},{"t":"choice","q":"La autora de estos cuentos, además de escribirlos…","o":["también hace las ilustraciones","solo escribe y otra persona dibuja","es la protagonista del cuento"],"a":0},{"t":"choice","q":"¿De qué país es la autora?","o":["Argentina","España","México"],"a":0},{"t":"open","q":"Completá la ficha lectora de «Secreto de familia»: título, autora, personajes principales y dónde transcurre","model":"Revisá con el libro delante: que los personajes y el lugar salgan del cuento, no de la imaginación."},{"t":"open","q":"Completá la ficha lectora de «Petit, el monstruo»: título, autora, personajes principales y dónde transcurre","model":"Igual que la anterior. Si duda con el lugar, que mire las ilustraciones."},{"t":"open","q":"Describí el lugar donde pasa una escena de «Secreto de familia». Usá por lo menos tres detalles que se vean en las ilustraciones","model":"Que nombre el lugar y agregue detalles concretos (objetos, colores, si es adentro o afuera, de día o de noche). «Una casa» sola no alcanza."},{"t":"open","q":"Escribí una recomendación breve de «Petit, el monstruo» para un compañero","model":"Dos partes: de qué trata (sin contar el final) y por qué lo recomienda."},{"t":"open","q":"¿En qué se parecen los cuentos de esta autora que leíste? Pensá en los personajes, en las ilustraciones o en cómo terminan","model":"Pregunta de comparación: tiene que nombrar al menos dos libros y una semejanza concreta."},{"t":"open","q":"Escribí una nota con datos sobre la autora: qué hace, de dónde es y qué libros suyos leíste","model":"Es el formato «nota de datos sobre la vida y obra del autor» que pide el programa: oraciones cortas con información, no opinión."}],"rules":"\n<div class=\"rsec\"><h4>Cómo completar una ficha lectora</h4>\n<div class=\"rrow\"><span class=\"rl\">Título</span><span class=\"ra\">está en la tapa</span></div>\n<div class=\"rrow\"><span class=\"rl\">Autor o autora</span><span class=\"ra\">también en la tapa</span></div>\n<div class=\"rrow\"><span class=\"rl\">Personajes</span><span class=\"ra\">quiénes aparecen</span></div>\n<div class=\"rrow\"><span class=\"rl\">Lugar</span><span class=\"ra\">dónde pasa la historia</span></div>\n<p class=\"exline\">Todo sale <b>del libro</b>. Si no te acordás, volvé a mirarlo.</p></div>\n<div class=\"rsec\"><h4>Describir un lugar</h4>\n<p class=\"exline\">No alcanza con nombrarlo (\"una plaza\"). Contá <b>cómo es</b>: qué objetos hay, de qué color, si es adentro o afuera, de día o de noche.</p>\n<div class=\"warn\"><b>Para el adulto:</b> estas consignas se contestan con el libro delante. Lo que se evalúa es que lo que dice <b>salga del cuento</b>.</div></div>","books":[{"id":"secreto-de-familia","title":"Secreto de familia"},{"id":"petit","title":"Petit, el monstruo"}]},{"id":"l8","dot":"🧦","name":"Instructivos","title":"Textos instructivos","sub":"Leer en orden · recetas, títeres, reglamentos","ex":[{"t":"choice","q":"¿Para qué sirve el texto «Cómo hacer un títere con una media»?","o":["Para contar una historia","Para explicar cómo hacer algo","Para informar una noticia"],"a":1},{"t":"fill","q":"¿Cuántos botones se necesitan para hacer el títere?","labels":[""],"a":["re:^(2|dos)$"]},{"t":"choice","q":"¿Qué hay que hacer ANTES de pegar los botones?","o":["Pegar la lana","Marcar dónde van los ojos","Esperar que se seque"],"a":1},{"t":"order","q":"Ordená estos pasos como aparecen en el texto","items":["Pegar la lana","Esperar que se seque","Marcar los ojos","Pegar los botones"],"a":["Marcar los ojos","Pegar los botones","Pegar la lana","Esperar que se seque"]},{"t":"choice","q":"En el texto, las palabras «marcá», «pegá» y «esperá» sirven para…","o":["decirle al lector qué tiene que hacer","nombrar los materiales","contar lo que hizo un personaje"],"a":0},{"t":"choice","q":"¿Qué pasaría si usás el títere antes del último paso?","o":["Los botones y la lana se podrían despegar","El títere quedaría más lindo","No pasaría nada"],"a":0},{"t":"open","q":"Escribí el reglamento de un juego que conozcas. Poné el nombre del juego, cuántos juegan y por lo menos tres reglas","model":"El programa pide «prescribir acciones a un destinatario real». Que las reglas se entiendan sin explicación extra: probá leérselas a alguien que no conozca el juego."},{"t":"open","q":"Escribí una receta fácil que sepas hacer. Poné ingredientes y pasos ordenados","paper":true,"model":"Que tenga las dos partes (qué se necesita y qué se hace) y que los pasos vayan en orden."}],"rules":"\n<div class=\"rsec\"><h4>Las partes de un texto instructivo</h4>\n<div class=\"rrow\"><span class=\"rl\">Título</span><span class=\"ra\">qué se va a hacer</span></div>\n<div class=\"rrow\"><span class=\"rl\">Materiales o ingredientes</span><span class=\"ra\">qué se necesita</span></div>\n<div class=\"rrow\"><span class=\"rl\">Pasos</span><span class=\"ra\">en orden, uno por uno</span></div>\n<div class=\"warn\">Se lee <b>despacio y en orden</b>. Si te salteás un paso o cambiás el orden, lo que estás haciendo sale mal.</div></div>\n<div class=\"rsec\"><h4>Texto para leer</h4>\n<div class=\"rrow\"><span class=\"rl\" style=\"text-align:left\"><b>Cómo hacer un títere con una media</b><br><br>\n<b>Materiales:</b> una media vieja, dos botones, lana, pegamento y un marcador.<br><br>\n1. Poné la mano adentro de la media para ver dónde quedan los ojos.<br>\n2. Marcá con el marcador el lugar de los ojos.<br>\n3. Sacá la mano y pegá los dos botones en las marcas.<br>\n4. Pegá la lana arriba, como si fuera el pelo.<br>\n5. Esperá a que se seque el pegamento antes de usarlo.</span></div></div>"},{"id":"l9","dot":"🦕","name":"Informativos","title":"Textos informativos y noticias","sub":"Leer para aprender · completar fichas","ex":[{"t":"fill","q":"Completá la ficha con datos del texto «Los dinosaurios»","labels":["Un dinosaurio herbívoro","Un dinosaurio carnívoro"],"a":["re:^diplodoc(o|us)$","re:^tiranosaurio( rex)?$"]},{"t":"choice","q":"¿Qué comían los dinosaurios herbívoros?","o":["Carne","Plantas","Piedras"],"a":1},{"t":"choice","q":"¿Para qué le servía el cuello tan largo al Diplodoco?","o":["Para correr más rápido","Para alcanzar las hojas de los árboles","Para nadar"],"a":1},{"t":"choice","q":"Según el texto, ¿qué son los fósiles?","o":["Dinosaurios que siguen vivos","Restos de huesos que quedaron en las rocas","Plantas muy antiguas"],"a":1},{"t":"choice","q":"¿Los dinosaurios vivieron al mismo tiempo que las personas?","o":["Sí","No"],"a":1},{"t":"fill","q":"¿Cómo se llama el dinosaurio encontrado en la Argentina que nombra el texto?","labels":[""],"a":["re:^argentinosaur(io|us)$"]},{"t":"choice","q":"Leé este título: <b>«Encuentran en Neuquén los huesos de un dinosaurio gigante»</b>. ¿Qué tipo de texto es?","o":["Un cuento","Una noticia","Un poema"],"a":1},{"t":"open","q":"Escribí tres cosas nuevas que aprendiste leyendo el texto","model":"Que sean datos del texto, dichos con sus palabras y en oraciones completas."}],"rules":"\n<div class=\"rsec\"><h4>Leer para aprender</h4>\n<p class=\"exline\">Un texto informativo cuenta <b>datos reales</b> sobre un tema. Para completar una ficha, buscá en el texto la <b>palabra exacta</b> que responde cada dato y releé el párrafo donde aparece.</p>\n<p class=\"exline\">Una <b>noticia</b> cuenta algo real que pasó hace poco. Su título resume lo más importante.</p></div>\n<div class=\"rsec\"><h4>Texto para leer</h4>\n<div class=\"rrow\"><span class=\"rl\" style=\"text-align:left\"><b>Los dinosaurios</b><br><br>\nLos dinosaurios vivieron hace millones de años, mucho antes de que existieran las personas. Algunos eran enormes y otros eran del tamaño de una gallina.<br><br>\nHabía dinosaurios herbívoros, que comían plantas, y carnívoros, que comían carne. El Tiranosaurio era carnívoro y tenía dientes muy filosos. El Diplodoco era herbívoro y tenía un cuello larguísimo para alcanzar las hojas de los árboles.<br><br>\nHoy sabemos cómo eran gracias a los fósiles: restos de huesos que quedaron guardados en las rocas durante muchísimo tiempo.<br><br>\nEn la Argentina se encontraron fósiles de dinosaurios gigantes, como el Argentinosaurio.</span></div></div>"},{"id":"l10","dot":"🎵","name":"Poesía","title":"Rimas, adivinanzas y limericks","sub":"Jugar con las palabras","ex":[{"t":"choice","q":"¿Qué palabra rima con <b>ratón</b>?","o":["gato","botón","mesa"],"a":1},{"t":"choice","q":"¿Qué palabra rima con <b>estrella</b>?","o":["bella","sol","cielo"],"a":0},{"t":"choice","q":"¿Qué palabra rima con <b>helado</b>?","o":["frío","nieve","pescado"],"a":2},{"t":"choice","q":"¿Cuál de estas palabras NO rima con <b>flor</b>?","o":["color","calor","mesa"],"a":2},{"t":"choice","q":"Adiviná: <i>«Tengo agujas y no sé coser, tengo números y no sé leer.»</i> ¿Qué es?","o":["Un reloj","Un libro","Una tijera"],"a":0},{"t":"choice","q":"Adiviná: <i>«Tiene orejas largas, salta sin parar y le encantan las zanahorias.»</i> ¿Quién es?","o":["El pato","El perro","El conejo"],"a":2},{"t":"choice","q":"Leé este limerick:<br><i>Había una vaca en Tandil<br>que viajaba en un tren de marfil.<br>Mugía en el vagón,<br>comía turrón<br>y bailaba un tango en Tandil.</i><br><br>¿Qué palabra rima con <b>vagón</b>?","o":["tren","turrón","vaca"],"a":1},{"t":"choice","q":"En el mismo limerick, ¿qué palabra rima con <b>marfil</b>?","o":["Tandil","tango","mugía"],"a":0},{"t":"open","q":"Inventá una adivinanza sobre un animal. Dá pistas, pero no digas su nombre","model":"Que funcione: si se la leés a alguien, ¿la puede adivinar? Si dice el nombre del animal en la adivinanza, no vale."},{"t":"open","q":"Escribí dos versos que rimen entre sí","model":"Que la última palabra de cada verso termine con el mismo sonido."}],"rules":"\n<div class=\"rsec\"><h4>¿Cuándo riman dos palabras?</h4>\n<p class=\"exline\">Cuando <b>terminan con el mismo sonido</b>.</p>\n<div class=\"rrow\"><span class=\"rl\">ma<b>no</b> / ena<b>no</b></span><span class=\"ra\">riman</span></div>\n<div class=\"rrow\"><span class=\"rl\">ma<b>no</b> / so<b>pa</b></span><span class=\"ra\">no riman</span></div>\n<div class=\"warn\"><b>Truco:</b> decí las dos palabras en voz alta y escuchá solo el final. Si suena igual, riman.</div></div>\n<div class=\"rsec\"><h4>Adivinanzas</h4>\n<p class=\"exline\">Describen algo con <b>pistas</b>, sin decir su nombre. Por ejemplo: <i>«Es amarilla por fuera, blanca por dentro, y los monos la pelan.»</i></p></div>\n<div class=\"rsec\"><h4>Limericks</h4>\n<p class=\"exline\">Son poemas cortos y disparatados, de cinco versos. El 1º, el 2º y el 5º riman entre sí; el 3º y el 4º riman entre ellos.</p></div>"},{"id":"l11","dot":"🅱️","name":"Ortografía +","title":"Ortografía y separación de palabras","sub":"B antes de consonante · MB · MP · R · RR","ex":[{"t":"fill","q":"Completá con B o V y escribí la palabra entera","labels":["__lanco","__razo","li__ro","som__rero"],"a":["blanco","brazo","libro","sombrero"]},{"t":"fill","q":"Completá con B o V y escribí la palabra entera","labels":["ca__le","__lusa","pue__lo"],"a":["cable","blusa","pueblo"]},{"t":"choice","q":"¿Cuál está bien escrita?","o":["havlar","hablar"],"a":1},{"t":"fill","q":"Completá con MB o MP y escribí la palabra entera","labels":["ca__iar","e__ezar","ho__ro","li__io"],"a":["cambiar","empezar","hombro","limpio"]},{"t":"fill","q":"Completá con R o RR y escribí la palabra entera","labels":["pe__a (la fruta)","a__oz","__isa","ca__eta"],"a":["pera","arroz","risa","carreta"]},{"t":"fill","q":"Separá las palabras y escribí la oración","h":"MIMAMÁMEREGALÓUNLIBRO.","labels":[""],"a":["mi mama me regalo un libro"]},{"t":"fill","q":"Separá las palabras y escribí la oración","h":"LAVACACOMEPASTOENELCAMPO.","labels":[""],"a":["la vaca come pasto en el campo"]},{"t":"open","q":"Escribí una oración que tenga una palabra con BR y otra con MP","model":"Revisá las dos palabras y que la oración tenga mayúscula al principio y punto al final."}],"rules":"\n<div class=\"rsec\"><h4>1. Antes de L y R va siempre B</h4>\n<div class=\"rrow\"><span class=\"rl\">ha<b>bl</b>ar, ta<b>bl</b>a</span><span class=\"ra\">BL</span></div>\n<div class=\"rrow\"><span class=\"rl\">a<b>br</b>igo, ca<b>br</b>a</span><span class=\"ra\">BR</span></div>\n<div class=\"warn\">En castellano <b>no existen</b> «vl» ni «vr». Si después viene L o R, la letra es <b>B</b>, sin dudar.</div></div>\n<div class=\"rsec\"><h4>2. MB y MP (repaso)</h4>\n<p class=\"exline\">Antes de B y P va <b>M</b>, nunca N: ta<b>mb</b>ién, co<b>mp</b>rar.</p></div>\n<div class=\"rsec\"><h4>3. R y RR (repaso)</h4>\n<p class=\"exline\">Suena fuerte entre vocales: <b>RR</b> (ja<b>rr</b>a). Al principio de la palabra, aunque suene fuerte, va <b>una sola R</b> (<b>r</b>opa). Si suena suave, una sola (ca<b>r</b>a).</p></div>\n<div class=\"rsec\"><h4>4. Separar las palabras</h4>\n<p class=\"exline\">Cada palabra va separada por un espacio. Las palabras cortitas como <b>a</b>, <b>y</b>, <b>el</b>, <b>en</b>, <b>un</b> también son palabras y van solas.</p>\n<div class=\"warn\">Para revisar: <b>señalá con el dedo</b> cada palabra mientras la leés en voz alta. Si con un solo toque dijiste dos palabras, falta un espacio.</div></div>"}]}]};
